aggregator.pseudocode:
class Aggregator:
    def __init__(self, expected, timeout, store):
        self.expected = expected  # 완료 조건: 메시지 개수
        self.timeout = timeout  # 완료 조건: 시간
        self.store = store  # 영속 저장소 {상관ID: (메시지목록, 시작시각)}

    def on_message(self, msg, now):
        cid = msg.correlation_id  # 관련 메시지 식별
        msgs, started = self.store.get(cid, ([], now))
        msgs.append(msg)
        if len(msgs) >= self.expected:  # 완료 → 하나로 결합
            self.store.delete(cid)
            return combine(msgs)  # 집계 전략 (예: 병합·합계)
        self.store.put(cid, (msgs, started))
        return None  # 미완료: 대기

    def on_tick(self, now):
        for cid, (msgs, started) in list(self.store.items()):
            if now - started >= self.timeout:  # 시간 초과
                self.store.delete(cid)
                publish(combine_partial(msgs)) # 부분 결과 처리

ai-watermarking.pseudocode:
def is_green(prev_tok, tok, key, gamma=0.5):
    # 이전 토큰 + 비밀키로 어휘를 재현 가능하게 분할
    return prf(key, prev_tok, tok) < gamma  # prf: 0~1 값

def generate_step(logits, prev_tok, key, delta=2.0):
    for tok in range(len(logits)):
        if is_green(prev_tok, tok, key):
            logits[tok] += delta  # 그린 토큰 선호
    return sample(softmax(logits))

def detect(tokens, key, gamma=0.5):
    T = len(tokens) - 1
    g = sum(is_green(tokens[i - 1], tokens[i], key)
            for i in range(1, len(tokens)))
    # 그린 토큰 비율이 우연(γ)보다 유의하게 높은가
    z = (g - gamma * T) / sqrt(T * gamma * (1 - gamma))
    return z > 4.0  # 워터마크(AI 생성)로 판정

alpha-algorithm.pseudocode:
def footprint(log):  # log: 트레이스(활동 문자열) 목록
    acts = {a for t in log for a in t}
    follows = {(t[i], t[i + 1]) for t in log
               for i in range(len(t) - 1)}  # 직접 후행 >
    rel = {}
    for a in acts:
        for b in acts:
            ab = (a, b) in follows
            ba = (b, a) in follows
            if ab and not ba:
                rel[a, b] = '→'  # 인과
            elif ba and not ab:
                rel[a, b] = '←'
            elif ab and ba:
                rel[a, b] = '‖'  # 병렬
            else:
                rel[a, b] = '#'  # 무관 (선택 관계)
    starts = {t[0] for t in log}  # 시작 활동 TI
    ends = {t[-1] for t in log}  # 종료 활동 TO
    return rel, starts, ends
# 다음 단계: 인과로 연결되고 내부가 무관인
# 최대 집합 쌍 (A, B)마다 플레이스 p(A,B) 생성

alpha-beta-pruning.pseudocode:
INF = float('inf')

def alphabeta(node, depth, a, b, is_max):
    # a(α): MAX가 보장한 하한, b(β): MIN이 보장한 상한
    if depth == 0 or node.is_terminal():
        return evaluate(node)
    if is_max:
        value = -INF
        for child in node.children():
            v = alphabeta(child, depth - 1, a, b, False)
            value = max(value, v)
            a = max(a, value)
            if a >= b:
                break  # β 절단: MIN이 이 분기를 택하지 않음
        return value
    value = INF
    for child in node.children():
        v = alphabeta(child, depth - 1, a, b, True)
        value = min(value, v)
        b = min(b, value)
        if a >= b:
            break  # α 절단: MAX가 이 분기를 택하지 않음
    return value

alpha-blending.pseudocode:
def render(opaque, transparent, fb, eye):
    for obj in opaque:  # 1) 불투명 먼저 (깊이 쓰기)
        draw(obj, fb)
    # 2) 반투명은 시점에서 먼 것부터 (뒤 → 앞)
    far_first = sorted(transparent,
                       key=lambda o: -distance(o, eye))
    for obj in far_first:
        for x, y, src, a in fragments(obj):
            dst = fb[y][x]
            # over 연산: C = αCsrc + (1 − α)Cdst
            fb[y][x] = a * src + (1 - a) * dst

anti-join.pseudocode:
def nl_anti_join(outer, inner, match):
    for o in outer:
        found = False
        for i in inner:
            if match(o, i):
                found = True
                break  # 일치 발견 즉시 중단
        if not found:
            yield o  # 일치 행이 없는 외부 행만 반환

def hash_anti_join(outer, inner, key):
    built = {key(i) for i in inner}  # 내부로 해시 빌드
    for o in outer:
        if key(o) not in built:
            yield o

# NOT IN은 내부 키에 NULL이 하나라도 있으면
