apriori-algorithm.pseudocode:
def apriori(transactions, min_sup):
    # transactions: frozenset 항목집합 목록
    n = len(transactions)
    def support(s):
        return sum(1 for t in transactions if s <= t) / n
    items = {frozenset([i])
             for t in transactions for i in t}
    L = {s for s in items if support(s) >= min_sup}
    result, k = set(L), 2
    while L:
        # 조인: 빈발 (k-1)-집합 두 개로 k-후보 생성
        cand = {a | b for a in L for b in L
                if len(a | b) == k}
        # 가지치기: 모든 (k-1) 부분집합이 빈발해야 유지
        cand = {c for c in cand
                if all(c - {i} in L for i in c)}
        L = {c for c in cand if support(c) >= min_sup}
        result |= L
        k += 1
    return result

area-under-curve.pseudocode:
def auc(scores, labels):
    pos = [s for s, y in zip(scores, labels) if y == 1]
    neg = [s for s, y in zip(scores, labels) if y == 0]
    wins = 0.0
    for p in pos:  # 모든 (양성, 음성) 쌍 비교
        for q in neg:
            if p > q:
                wins += 1.0  # 양성이 더 높은 점수
            elif p == q:
                wins += 0.5  # 동점은 절반
    return wins / (len(pos) * len(neg))
# = P(양성 점수 > 음성 점수) = ROC 곡선 아래 면적

asil.pseudocode:
def asil(s, e, c):
    # s: 0~3, e: 0~4, c: 0~3 (ISO 26262 Part 3)
    if s == 0 or e == 0 or c == 0:
        return 'QM'  # 안전 요구 없음
    total = s + e + c  # 표의 규칙성: 합으로 결정
    if total == 10:
        return 'D'  # S3·E4·C3
    if total == 9:
        return 'C'
    if total == 8:
        return 'B'
    if total == 7:
        return 'A'
    return 'QM'  # 합 6 이하

attribute-closure.pseudocode:
def closure(X, fds):
    # fds: [(좌변 집합, 우변 집합), ...]
    result = set(X)
    changed = True
    while changed:  # 더 이상 늘지 않을 때까지 반복
        changed = False
        for lhs, rhs in fds:
            if lhs <= result and not rhs <= result:
                result |= rhs  # 결정자 포함 시 종속 속성 추가
                changed = True
    return result

def is_superkey(X, fds, attrs):
    return closure(X, fds) >= set(attrs)

def is_candidate_key(X, fds, attrs):
    # 슈퍼키이면서 원소 하나만 빼도 슈퍼키가 아니어야 함
    return is_superkey(X, fds, attrs) and all(
        not is_superkey(set(X) - {a}, fds, attrs)
        for a in X)

audio-fingerprinting.pseudocode:
def fingerprints(peaks, fan_out=5):
    # peaks: (시각, 주파수) 목록, 시각순 정렬
    out = []
    for i, (t1, f1) in enumerate(peaks):
        for t2, f2 in peaks[i + 1:i + 1 + fan_out]:
            h = (f1, f2, t2 - t1)  # 앵커-타깃 쌍 해시
            out.append((h, t1))
    return out

def match(query_fp, db):  # db: 해시 → [(곡ID, 시각)]
    votes = {}
    for h, tq in query_fp:
        for song, ts in db.get(h, []):
            key = (song, ts - tq)  # 오프셋이 일정 = 같은 곡
            votes[key] = votes.get(key, 0) + 1
    if not votes:
        return None
    return max(votes, key=votes.get)[0]

audit-log.pseudocode:
def append_log(log, event):
    prev = log[-1]['hash'] if log else '0' * 64
    h = sha256(prev + serialize(event))  # 이전 해시와 연결
    log.append({'event': event, 'prev': prev, 'hash': h})

def verify_log(log):
    prev = '0' * 64
    for i, rec in enumerate(log):
        expect = sha256(prev + serialize(rec['event']))
        if rec['prev'] != prev or rec['hash'] != expect:
            return i  # 이 위치부터 위변조·삭제 의심
        prev = rec['hash']
    return None  # 체인 무결

auto-scaling.pseudocode:
def desired_replicas(current, metric, target,
                     lo, hi, tolerance=0.1):
    # 쿠버네티스 HPA 방식: 현재값/목표값 비율로 조정
    ratio = metric / target
    if abs(ratio - 1.0) <= tolerance:
        return current  # 허용 오차 내면 유지(진동 방지)
    desired = ceil(current * ratio)
    return max(lo, min(hi, desired))  # 최소·최대 범위

# 예: 4대, CPU 90% / 목표 60% → ceil(4 × 1.5) = 6대

automatic-differentiation.pseudocode:
class Var:  # 후진 모드 자동 미분
    def __init__(self, value, parents=()):
        self.value, self.grad = value, 0.0
        self.parents = parents  # (부모, 국소 미분값)
    def __add__(self, o):
        return Var(self.value + o.value,
                   ((self, 1.0), (o, 1.0)))
    def __mul__(self, o):
        return Var(self.value * o.value,
                   ((self, o.value), (o, self.value)))

def backward(out):
    order, seen = [], set()
    def topo(v):  # 연산 그래프 위상 정렬
        if id(v) not in seen:
            seen.add(id(v))
            for p, _ in v.parents:
                topo(p)
            order.append(v)
    topo(out)
    out.grad = 1.0
    for v in reversed(order):  # 출력에서 입력 방향으로
        for p, local in v.parents:
            p.grad += v.grad * local  # 연쇄법칙 누적

automatic-repeat-request.pseudocode:
def go_back_n(frames, N, send, wait):
    # send(seq, frame): 전송
    # wait(): ('ack', n) 또는 ('timeout', None)
    base = next_seq = 0
    while base < len(frames):
        # 윈도우(크기 N) 안의 미전송 프레임 송신
        while next_seq < min(base + N, len(frames)):
            send(next_seq, frames[next_seq])
            next_seq += 1
        ev, ack = wait()  # base 프레임 타이머 기준
        if ev == 'ack' and ack >= base:
            base = ack + 1  # 누적 ACK: ack까지 수신 확인
        elif ev == 'timeout':
            next_seq = base  # base부터 전부 재전송

back-face-culling.pseudocode:
def is_back_face(v0, v1, v2, eye):
    # 정점이 반시계 순서 → 외적이 바깥쪽 법선
    n = cross(sub(v1, v0), sub(v2, v0))
    view = sub(v0, eye)  # 시점 → 다각형 시선 벡터
    return dot(n, view) >= 0  # 0 이상이면 뒷면(측면 포함)

def cull(polygons, eye):
    visible = []
    for poly in polygons:
        v0, v1, v2 = poly[0], poly[1], poly[2]
        if not is_back_face(v0, v1, v2, eye):
            visible.append(poly)  # 앞면만 다음 단계로
    return visible

back-substitution.pseudocode:
def back_substitution(A, b):
    # A: n×n 상삼각행렬 (대각 성분 ≠ 0)
    n = len(b)
    x = [0.0] * n
    for i in range(n - 1, -1, -1):  # 마지막 행부터 역순
        s = b[i]
        for j in range(i + 1, n):
            s -= A[i][j] * x[j]  # 이미 구한 해 대입
        x[i] = s / A[i][i]
    return x  # 연산량 O(n²)

