base-case.pseudocode:
def factorial(n):
    if n < 0:
        raise ValueError  # 입력 검증
    if n <= 1:  # 기저 조건: 직접 반환
        return 1
    return n * factorial(n - 1)  # 기저 쪽으로 축소

def fib(n):
    if n == 0:  # 기저 조건 1
        return 0
    if n == 1:  # 기저 조건 2
        return 1
    return fib(n - 1) + fib(n - 2)

basic-encoding-rules.pseudocode:
def ber_length(n):
    if n < 128:
        return [n]  # 단형식: 1바이트
    body = []
    while n:
        body.insert(0, n & 0xFF)
        n >>= 8
    return [0x80 | len(body)] + body  # 장형식

def ber_tlv(tag, value):
    # tag: 1바이트 태그, value: 바이트 리스트
    return [tag] + ber_length(len(value)) + value

# 예: INTEGER 5 → [0x02, 0x01, 0x05]
# SEQUENCE { INTEGER 5 } → [0x30, 0x03, 0x02, 0x01, 0x05]

bayesian-filter.pseudocode:
def train(spam_docs, ham_docs):
    count = {'spam': {}, 'ham': {}}
    for label, docs in (('spam', spam_docs),
                        ('ham', ham_docs)):
        for doc in docs:
            for w in set(doc):  # 단어가 등장한 문서 수
                c = count[label]
                c[w] = c.get(w, 0) + 1
    return count, len(spam_docs), len(ham_docs)

def spam_prob(words, model):
    count, ns, nh = model
    log_s = log(ns / (ns + nh))  # 사전확률 P(스팸)
    log_h = log(nh / (ns + nh))
    for w in set(words):
        # 라플라스 평활로 0 확률 방지
        ps = (count['spam'].get(w, 0) + 1) / (ns + 2)
        ph = (count['ham'].get(w, 0) + 1) / (nh + 2)
        log_s += log(ps)
        log_h += log(ph)
    return 1 / (1 + exp(log_h - log_s))  # P(스팸 | 단어)

bcrypt.pseudocode:
def bcrypt(cost, salt, password):
    state = eks_blowfish_setup(cost, salt, password)
    ctext = 'OrpheanBeholderScryDoubt'  # 192비트 상수
    for _ in range(64):
        ctext = encrypt_ecb(state, ctext)
    return encode(cost, salt, ctext)

def eks_blowfish_setup(cost, salt, key):
    state = initial_state()  # π 소수부로 P배열·S박스 초기화
    state = expand_key(state, salt, key)
    for _ in range(2 ** cost):  # 비용 지수만큼 키 스트레칭
        state = expand_key(state, 0, key)
        state = expand_key(state, 0, salt)
    return state

beam-search.pseudocode:
def beam_search(start, expand, score, k, depth):
    beam = [start]
    for _ in range(depth):
        candidates = []
        for node in beam:
            candidates.extend(expand(node))  # 후속 노드 생성
        if not candidates:
            break
        candidates.sort(key=score, reverse=True)
        beam = candidates[:k]  # 상위 k개만 유지, 나머지 폐기
    return max(beam, key=score)
# 유망 경로를 버릴 수 있어 완전성·최적성 미보장

behavior-tree.pseudocode:
def tick(node, bb):  # bb: 블랙보드(공유 상태)
    if node.kind in ('action', 'condition'):
        return node.run(bb)  # SUCCESS·FAILURE·RUNNING
    if node.kind == 'sequence':
        for child in node.children:
            r = tick(child, bb)
            if r != SUCCESS:  # 실패·진행 중이면 중단
                return r
        return SUCCESS
    if node.kind == 'selector':
        for child in node.children:
            r = tick(child, bb)
            if r != FAILURE:  # 성공·진행 중이면 중단
                return r
        return FAILURE
    if node.kind == 'inverter':  # 데코레이터 예
        r = tick(node.child, bb)
        flip = {SUCCESS: FAILURE, FAILURE: SUCCESS}
        return flip.get(r, r)  # RUNNING은 그대로

belady-anomaly.pseudocode:
def fifo_faults(refs, n):
    frames, faults = [], 0
    for p in refs:
        if p not in frames:
            faults += 1
            if len(frames) == n:
                frames.pop(0)  # 가장 먼저 적재된 페이지 교체
            frames.append(p)
    return faults

refs = [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]
print(fifo_faults(refs, 3))  # 9
