binary-insertion-sort.pseudocode:
def binary_insertion_sort(a):
    for i in range(1, len(a)):
        key = a[i]
        lo, hi = 0, i  # 정렬된 a[0..i-1]에서 탐색
        while lo < hi:  # 이진 탐색: 비교 O(log i)
            mid = (lo + hi) // 2
            if a[mid] <= key:  # 같으면 오른쪽 → 안정성
                lo = mid + 1
            else:
                hi = mid
        for j in range(i, lo, -1):  # 이동은 여전히 O(i)
            a[j] = a[j - 1]
        a[lo] = key
    return a

binary-search.pseudocode:
def binary_search(a, target):  # a는 오름차순 정렬
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2  # 오버플로 방지
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1  # 오른쪽 절반
        else:
            hi = mid - 1  # 왼쪽 절반
    return -1  # 없음, T(n)=T(n/2)+O(1) → O(log n)

binary-search-tree.pseudocode:
def search(node, key):
    while node is not None:
        if key == node.key:
            return node
        # 작으면 왼쪽, 크면 오른쪽 서브트리로
        node = node.left if key < node.key else node.right
    return None  # 탐색 실패

def insert(node, key):
    if node is None:
        return Node(key)  # 빈 자리에 새 노드
    if key < node.key:
        node.left = insert(node.left, key)
    elif key > node.key:
        node.right = insert(node.right, key)
    return node  # 중복 키는 삽입하지 않음

binary-semaphore.pseudocode:
class BinarySemaphore:
    def __init__(self, value=1):  # 1: 상호배제, 0: 신호용
        self.value = value
        self.queue = []  # 대기 스레드 목록

    def P(self):  # wait: 원자적으로 수행
        if self.value == 1:
            self.value = 0
        else:
            self.queue.append(current_thread())
            block()  # 대기 상태로 전환

    def V(self):  # signal: 원자적으로 수행
        if self.queue:
            wakeup(self.queue.pop(0))  # 값은 0 유지, 진입권 이양
        else:
            self.value = 1

bit-sliced-signature-file.pseudocode:
def bssf_query(slices, query_sig, n_docs):
    # slices[j]: 비트 위치 j의 문서별 비트(정수 비트맵)
    candidates = (1 << n_docs) - 1  # 모든 문서 후보
    for j, bit in enumerate(query_sig):
        if bit == 1:  # 질의 1비트 슬라이스만 읽음
            candidates &= slices[j]
    # 후보 비트맵 → 문서 번호 (false drop 검사 필요)
    return [d for d in range(n_docs)
            if candidates >> d & 1]

bloom-filter.pseudocode:
class BloomFilter:
    def __init__(self, m, hashes):
        self.bits = [0] * m  # m비트 배열
        self.hashes = hashes  # k개 해시 함수

    def add(self, x):
        for h in self.hashes:
            self.bits[h(x) % len(self.bits)] = 1

    def might_contain(self, x):
        # 하나라도 0이면 확실히 없음(거짓 음성 없음)
        # 모두 1이면 '아마 있음'(거짓 양성 가능)
        return all(self.bits[h(x) % len(self.bits)]
                   for h in self.hashes)

# 최적 해시 수 k = (m / n) * ln 2

bond-energy-algorithm.pseudocode:
def bond(aa, x, y):
    if x is None or y is None:  # 경계 열은 0
        return 0
    return sum(aa[z][x] * aa[z][y] for z in range(len(aa)))

def cont(aa, i, k, j):  # Ai-Ak-Aj 배치 시 기여도
    return (2 * bond(aa, i, k) + 2 * bond(aa, k, j)
            - 2 * bond(aa, i, j))

def bea(aa):
    n = len(aa)
    order = [0, 1]  # 처음 두 열 배치
    for k in range(2, n):
        best_pos, best = 0, None
        for pos in range(len(order) + 1):
            left = order[pos - 1] if pos > 0 else None
            right = order[pos] if pos < len(order) else None
            c = cont(aa, left, k, right)
            if best is None or c > best:
                best_pos, best = pos, c
        order.insert(best_pos, k)
    return order  # 행도 같은 순서로 재배치 → CA

branch-prediction.pseudocode:
# 2비트 포화 카운터: 0·1=Not Taken, 2·3=Taken
class TwoBitPredictor:
    def __init__(self, size):
        self.size = size
        self.pht = [1] * size  # 약한 Not Taken으로 시작

    def predict(self, pc):
        return self.pht[pc % self.size] >= 2  # True=Taken

    def update(self, pc, taken):
        i = pc % self.size
        if taken:
            self.pht[i] = min(3, self.pht[i] + 1)
        else:
            self.pht[i] = max(0, self.pht[i] - 1)

