def closeness(graph, v):
    # BFS로 v에서 각 노드까지 최단 거리 (무가중 그래프)
    dist, queue = {v: 0}, [v]
    for u in queue:
        for w in graph[u]:
            if w not in dist:
                dist[w] = dist[u] + 1
                queue.append(w)
    total = sum(dist.values())
    return (len(dist) - 1) / total if total else 0.0

# A-B, B-C, C-D, B-E 그래프: B = 4/5 = 0.80 (최고)

