collision-resistance.pseudocode:
def birthday_collision(h, n_bits, gen):
    # n비트 해시: 약 2^(n/2)번 시도로 충돌 기대
    seen = {}
    while True:
        x = gen()  # 무작위 입력
        d = h(x) & ((1 << n_bits) - 1)  # 하위 n비트만 사용
        if d in seen and seen[d] != x:
            return seen[d], x  # 다른 입력, 같은 해시
        seen[d] = x

# 32비트로 절단한 SHA-256 → 약 6.5만(2^16)번에 충돌
# 전체 256비트 → 2^128번 필요 (계산상 불가능)

