def ondemand(cpu, levels, up_threshold=80):
    # levels: 주파수 오름차순 [(freq, volt), ...] P-state
    load = cpu.utilization()  # 최근 샘플 구간 사용률 %
    f_max = levels[-1][0]
    if load > up_threshold:
        target = len(levels) - 1  # 즉시 최고 주파수
    else:
        need = f_max * load / 100  # 부하 비례 (단순화)
        target = 0
        while levels[target][0] < need:
            target += 1
    set_pstate(cpu, levels[target])

def set_pstate(cpu, level):
    freq, volt = level
    if freq > cpu.freq:
        cpu.set_voltage(volt)  # 상향: 전압 먼저 올림
        cpu.set_freq(freq)
    else:
        cpu.set_freq(freq)  # 하향: 주파수 먼저 내림
        cpu.set_voltage(volt)

earliest-deadline-first.pseudocode:
def edf(tasks, horizon):
    # tasks: [(이름, 실행시간 C, 주기=상대 마감 P)]
    jobs, timeline = [], []
    for t in range(horizon):
        for name, c, p in tasks:
            if t % p == 0:  # 주기마다 새 작업 도착
                jobs.append([t + p, name, c])  # 마감·이름·잔여
        if any(d <= t for d, _, _ in jobs):
            return 'deadline miss at %d' % t
        if not jobs:
            timeline.append('-')  # 유휴
            continue
        job = min(jobs)  # 마감 가장 이른 작업 (매 시점 재선택=선점)
        job[2] -= 1
        timeline.append(job[1])
        if job[2] == 0:
            jobs.remove(job)
    return timeline
# 예: [(T1,1,4), (T2,2,6), (T3,3,8)] U=0.958 → 성공

edge-relaxation.pseudocode:
def relax(u, v, w, dist, pred):
    if dist[u] + w < dist[v]:  # 더 짧은 경로 발견
        dist[v] = dist[u] + w
        pred[v] = u  # 경로 복원용 선행 정점
        return True
    return False

def bellman_ford(vertices, edges, s):
    dist = {v: INF for v in vertices}
    pred = {v: None for v in vertices}
    dist[s] = 0
    for _ in range(len(vertices) - 1):  # V-1회
        for u, v, w in edges:
            relax(u, v, w, dist, pred)
    for u, v, w in edges:  # 더 줄어들면 음수 사이클
        if dist[u] + w < dist[v]:
            raise ValueError('음수 사이클 존재')
    return dist, pred

