# 컴포넌트 저장소: 컴포넌트 종류별 entity_id -> 데이터
position = {}
velocity = {}
next_id = 0

def create_entity(**components):
    global next_id
    eid = next_id  # 엔티티는 단순 식별자
    next_id += 1
    if 'pos' in components:
        position[eid] = components['pos']
    if 'vel' in components:
        velocity[eid] = components['vel']
    return eid

def movement_system(dt):
    # 두 컴포넌트를 모두 가진 엔티티만 일괄 처리
    for eid in position.keys() & velocity.keys():
        x, y = position[eid]
        vx, vy = velocity[eid]
        position[eid] = (x + vx * dt, y + vy * dt)

def game_loop(dt):
    movement_system(dt)  # 시스템을 순서대로 실행

epsilon-transition.pseudocode:
def epsilon_closure(states, eps):
    # eps[q]: q에서 ε-전이 한 번으로 가는 상태 집합
    closure = set(states)
    stack = list(states)
    while stack:
        q = stack.pop()
        for r in eps.get(q, ()):
            if r not in closure:  # 처음 도달한 상태만 확장
                closure.add(r)
                stack.append(r)
    return closure

def accepts(word, start, finals, eps, delta):
    cur = epsilon_closure({start}, eps)
    for c in word:
        # 입력 c를 소비한 뒤 다시 ε-closure
        nxt = set()
        for q in cur:
            nxt |= delta.get((q, c), set())
        cur = epsilon_closure(nxt, eps)
    return bool(cur & finals)

