def check_privacy(records, qi, sensitive, k, l):
    groups = {}
    for r in records:
        key = tuple(r[a] for a in qi)  # 준식별자 값 조합
        groups.setdefault(key, []).append(r)
    # 동질집합 = groups의 각 값
    k_ok = all(len(g) >= k for g in groups.values())
    l_ok = all(len({r[sensitive] for r in g}) >= l
               for g in groups.values())
    return k_ok, l_ok  # k-익명성, l-다양성 여부

eui-64.pseudocode:
def mac_to_modified_eui64(mac):
    b = [int(x, 16) for x in mac.split(':')]  # 6바이트 MAC
    # OUI + FFFE + 장치 ID = 8바이트
    eui = b[0:3] + [0xFF, 0xFE] + b[3:6]
    eui[0] ^= 0x02  # U/L 비트(첫 바이트 7번째 비트) 반전
    groups = []
    for i in range(0, 8, 2):  # 16비트씩 4그룹
        groups.append('%x' % ((eui[i] << 8) | eui[i + 1]))
    return ':'.join(groups)  # 인터페이스 ID (하위 64비트)

def link_local(mac):
    return 'fe80::' + mac_to_modified_eui64(mac)

# link_local('00:1A:2B:3C:4D:5E') → 'fe80::21a:2bff:fe3c:4d5e'

event-driven-programming.pseudocode:
handlers = {}  # 이벤트 종류 -> 콜백 목록

def on(event_type, callback):
    # 핸들러 등록 (옵저버 패턴과 동일)
    handlers.setdefault(event_type, []).append(callback)

def run_loop(queue, wait_for_event):
    while True:
        if not queue:
            wait_for_event(queue)  # 입력·메시지 도착까지 대기
            continue
        etype, data = queue.pop(0)
        if etype == 'quit':
            break
        for cb in handlers.get(etype, []):
            cb(data)  # 핸들러는 짧게, 긴 작업은 위임

event-loop.pseudocode:
def event_loop(selector, timers):
    while True:
        # 가장 가까운 타이머 만료까지만 대기
        timeout = timers.next_timeout()
        events = selector.wait(timeout)  # I/O 준비 통지
        for fd, mask in events:
            handler = selector.handler_of(fd)
            handler(fd, mask)  # 논블로킹 콜백 실행
        for callback in timers.pop_expired():
            callback()  # 만료 타이머 처리
        # 콜백이 블로킹되면 모든 연결 처리가 멈춤

event-sourcing.pseudocode:
def apply(state, ev):
    # 이벤트 하나를 상태에 반영 (부수효과 없음)
    if ev['type'] == 'Opened':
        return 0
    if ev['type'] == 'Deposited':
        return state + ev['amount']
    if ev['type'] == 'Withdrawn':
        return state - ev['amount']
    return state

def load(log, snapshot=None):
    # 스냅샷 (상태, seq)가 있으면 그 이후 이벤트만 재생
    state, since = snapshot if snapshot else (None, 0)
    for ev in log:
        if ev['seq'] > since:
            state = apply(state, ev)
    return state

def withdraw(log, amount):
    balance = load(log)
    if balance < amount:
        raise ValueError('잔액 부족')
    # 기존 상태를 고치지 않고 새 이벤트를 추가만 함
    log.append({'seq': len(log) + 1, 'type': 'Withdrawn',
                'amount': amount})

exploration-exploitation.pseudocode:
def epsilon_greedy(n_arms, pull, steps, eps=0.1):
    count = [0] * n_arms
    value = [0.0] * n_arms  # 행동별 평균 보상 추정치
    for t in range(steps):
        if rand() < eps:
            a = rand_int(n_arms)  # 탐험: 무작위 행동
        else:
            a = value.index(max(value))  # 활용: 현재 최선
        r = pull(a)
        count[a] += 1
        value[a] += (r - value[a]) / count[a]  # 증분 평균
    return value

extent.pseudocode:
def lookup(extents, lblock):
    # extents: (논리 시작, 물리 시작, 길이), 논리 시작 순
    lo, hi = 0, len(extents) - 1
    while lo <= hi:  # 이진 탐색
        mid = (lo + hi) // 2
        ls, ps, n = extents[mid]
        if lblock < ls:
            hi = mid - 1
        elif lblock >= ls + n:
            lo = mid + 1
        else:
            return ps + (lblock - ls)  # 구간 내 오프셋
    return None  # 할당되지 않은 구멍(hole)

