# DFA: '01'로 끝나는 이진 문자열 수락
DELTA = {  # 전이함수 δ(상태, 입력) → 다음 상태
    ('q0', '0'): 'q1', ('q0', '1'): 'q0',
    ('q1', '0'): 'q1', ('q1', '1'): 'q2',
    ('q2', '0'): 'q1', ('q2', '1'): 'q0',
}
START, ACCEPT = 'q0', {'q2'}

def run_dfa(s):
    state = START  # 초기 상태 q0
    for ch in s:
        if (state, ch) not in DELTA:
            return False  # 정의되지 않은 입력 → 거부
        state = DELTA[(state, ch)]
    return state in ACCEPT  # 종료(수락) 상태 여부

firewall.pseudocode:
def filter_packet(pkt, rules, sessions):
    key = (pkt.src, pkt.sport, pkt.dst, pkt.dport)
    if key in sessions:  # 상태 검사: 기존 세션
        return 'ALLOW'
    for r in rules:  # 위에서부터 첫 일치 규칙
        if r.matches(pkt):
            if r.action == 'ALLOW':
                rev = (pkt.dst, pkt.dport,
                       pkt.src, pkt.sport)
                sessions.update({key, rev})  # 응답 허용
            return r.action
    return 'DENY'  # 기본 거부(Default Deny)

floyd-warshall-algorithm.pseudocode:
INF = float('inf')

def floyd_warshall(n, edges):
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for u, v, w in edges:  # 직접 간선 가중치로 초기화
        d[u][v] = min(d[u][v], w)
    for k in range(n):  # 경유 정점 k를 하나씩 추가
        for i in range(n):
            for j in range(n):
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]
    if any(d[i][i] < 0 for i in range(n)):
        raise ValueError('음수 사이클 존재')
    return d

