WEIGHTS = {  # 복잡도별 가중치 (저, 중, 고)
    'EI': (3, 4, 6), 'EO': (4, 5, 7), 'EQ': (3, 4, 6),
    'ILF': (7, 10, 15), 'EIF': (5, 7, 10),
}
LEVEL = {'low': 0, 'avg': 1, 'high': 2}

def unadjusted_fp(functions):
    # functions: [('EI', 'avg'), ('ILF', 'low'), ...]
    return sum(WEIGHTS[t][LEVEL[c]] for t, c in functions)

def adjusted_fp(ufp, gsc_scores):
    # IFPUG: 일반 시스템 특성 14개, 각 0~5점
    vaf = 0.65 + 0.01 * sum(gsc_scores)  # 0.65~1.35
    return ufp * vaf

# 예: EI 평균 2개 + ILF 저 1개 → UFP = 4*2 + 7 = 15

functional-dependency.pseudocode:
def closure(attrs, fds):
    # attrs: 속성 집합 X, fds: [(왼쪽 집합, 오른쪽 집합), ...]
    result = set(attrs)  # 반사: X ⊆ X+
    changed = True
    while changed:
        changed = False
        for lhs, rhs in fds:
            # 결정자가 모두 포함되면 종속자 추가 (이행)
            if lhs <= result and not rhs <= result:
                result |= rhs
                changed = True
    return result

def is_superkey(attrs, all_attrs, fds):
    return closure(attrs, fds) >= all_attrs  # X+ = 전체

garbage-collection.pseudocode:
def mark(roots):  # 루트에서 도달 가능한 객체 표시
    stack = list(roots)
    while stack:
        obj = stack.pop()
        if not obj.marked:
            obj.marked = True
            stack.extend(obj.refs)  # 참조 대상 계속 추적

def sweep(heap):  # 표시 안 된 객체 회수
    for obj in list(heap):
        if obj.marked:
            obj.marked = False  # 다음 GC를 위해 초기화
        else:
            heap.remove(obj)  # 도달 불가 → 메모리 해제

def collect(roots, heap):
    mark(roots)  # Stop-the-World 구간
    sweep(heap)

gaussian-quadrature.pseudocode:
def gauss_legendre_2pt(f, a, b):
    nodes = [-1 / sqrt(3), 1 / sqrt(3)]  # P2(x)의 근
    weights = [1.0, 1.0]
    mid, half = (a + b) / 2, (b - a) / 2  # [-1,1] → [a,b]
    return half * sum(w * f(mid + half * x)
                      for x, w in zip(nodes, weights))

# 2점으로 3차 다항식까지 정확
# gauss_legendre_2pt(lambda x: x ** 3, 0, 2) ≈ 4.0

