def is_generator(g, p):  # p: 소수, 군 Z_p*
    n = p - 1  # 군의 위수
    for q in prime_factors(n):
        # g^(n/q) = 1 이면 g는 진부분군에 속함
        if pow(g, n // q, p) == 1:
            return False
    return True  # 위수가 n → 생성원(원시근)

# is_generator(3, 7) → True, is_generator(2, 7) → False

generator-polynomial.pseudocode:
def crc_remainder(data_bits, gen_bits):
    # data_bits, gen_bits: '0'/'1' 문자열, 생성다항식 최고·최저 차수 계수는 1
    n = len(gen_bits) - 1  # 생성다항식 차수 = FCS 비트 수
    bits = list(data_bits + '0' * n)  # M(x)·x^n
    for i in range(len(data_bits)):
        if bits[i] == '1':  # 선두 비트가 1일 때만 XOR (모듈로-2 나눗셈)
            for j in range(len(gen_bits)):
                bits[i + j] = '0' if bits[i + j] == gen_bits[j] else '1'
    return ''.join(bits[-n:])  # 나머지 n비트 = FCS

def crc_check(frame_bits, gen_bits):
    n = len(gen_bits) - 1
    data, fcs = frame_bits[:-n], frame_bits[-n:]
    return crc_remainder(data, gen_bits) == fcs  # 재계산 값과 비교

# 예: crc_remainder('1101011011', '10011') → '1110'  (G(x) = x⁴+x+1)

go-back-n-arq.pseudocode:
def gbn_sender(frames, N):
    base = next_seq = 0  # 윈도 시작, 다음 송신 번호
    while base < len(frames):
        # 윈도 안이면 연속 송신
        while next_seq < min(base + N, len(frames)):
            send(next_seq, frames[next_seq])
            if base == next_seq:
                start_timer()  # 가장 오래된 미확인 프레임 기준
            next_seq += 1
        ev = wait_event()
        if ev.kind == 'ack' and ev.ack > base: # 누적 ACK: ack 직전까지 모두 확인
            base = ev.ack
            if base == next_seq:
                stop_timer()
            else:
                start_timer()
        elif ev.kind == 'timeout':  # 손실 → base부터 전부 재전송
            next_seq = base
    # 실제 순번은 mod 2^m, 송신 윈도 N ≤ 2^m − 1

def gbn_receiver():
    expected = 0
    while True:
        seq, data, ok = receive()
        # 순서 맞는 프레임만 수용 (수신 윈도 1)
        if ok and seq == expected:
            deliver(data)
            expected += 1
        send_ack(expected)  # 누적 ACK (어긋난 프레임은 폐기)

goal-seeking-analysis.pseudocode:
def goal_seek(model, target, lo, hi, tol=1e-6):
    # model(x)가 x에 대해 단조 증가라고 가정 (이분 탐색)
    for _ in range(100):
        mid = (lo + hi) / 2
        if model(mid) < target:
            lo = mid  # 목표 미달 → 입력 증가
        else:
            hi = mid
        if hi - lo < tol:
            break
    return (lo + hi) / 2

# 이익 = (가격 - 변동비) × Q - 고정비
profit = lambda q: (10_000 - 6_000) * q - 200_000_000
q = goal_seek(profit, 100_000_000, 0, 1e6)  # → 75,000개

gossip-protocol.pseudocode:
class Node:
    def __init__(self, peers):
        self.peers = peers  # 멤버십 목록
        self.state = {}  # {키: (값, 버전)}

    def merge(self, other_state):
        for key, (value, ver) in other_state.items():
            mine = self.state.get(key)
            if mine is None or ver > mine[1]:  # 더 최신 버전만 채택
                self.state[key] = (value, ver)

    def gossip_round(self, fanout):
        # 임의 이웃 k개
        for peer in random_sample(self.peers, fanout):
            peer.merge(self.state)  # push: 내 상태 전달
            self.merge(peer.state)  # pull: 상대 상태 병합

def run(node, interval):
    while True:
        node.gossip_round(fanout=3)
        sleep(interval)  # 주기 반복 → 최종적 일관성

goto-table.pseudocode:
def lr_parse(tokens, ACTION, GOTO):
    stack = [0]  # 상태 스택
    tokens = tokens + ['$']
    i = 0
    while True:
        s, a = stack[-1], tokens[i]
        act = ACTION[s].get(a)
        if act is None:
            return 'error'
        kind, val = act
        if kind == 'shift':
            stack.append(val)
            i += 1
        elif kind == 'reduce':
            lhs, rhs_len = val  # A → β, |β|
            del stack[len(stack) - rhs_len:]
            t = stack[-1]  # 축소 후 노출된 상태
            stack.append(GOTO[t][lhs])  # GOTO 참조
        else:
            return 'accept'

graph-attention-network.pseudocode:
def gat_layer(h, neighbors, W, attn, leaky):
    # h[i]: 노드 특징, neighbors[i]: 이웃 집합
    out = {}
    for i in h:
        scores = {}
        for j in neighbors[i] | {i}:  # 자기 자신 포함
            e = attn(concat(W @ h[i], W @ h[j]))
            scores[j] = leaky(e)  # LeakyReLU
        alpha = softmax(scores)  # 이웃 간 정규화
        out[i] = sum(alpha[j] * (W @ h[j]) for j in scores)
    return out  # 멀티헤드는 이 과정을 K번 후 연결

greedy-best-first-search.pseudocode:
def greedy_bfs(start, goal, neighbors, h):
    import heapq
    frontier = [(h(start), start)]
    came_from = {start: None}
    while frontier:
        _, cur = heapq.heappop(frontier)  # h 최소 노드
        if cur == goal:
            return reconstruct(came_from, goal)
        for nxt in neighbors(cur):
            if nxt not in came_from:
                came_from[nxt] = cur
                # g(비용) 무시, 휴리스틱 h만으로 평가
                heapq.heappush(frontier, (h(nxt), nxt))
    return None  # 실패

grid-search.pseudocode:
def grid_search(grid, evaluate):
    # grid: {파라미터: [후보값...]}
    from itertools import product
    keys = list(grid)
    best_score, best_params = -1e18, None
    for combo in product(*(grid[k] for k in keys)):
        params = dict(zip(keys, combo))
        score = evaluate(params)  # 교차검증 점수
        if score > best_score:
            best_score, best_params = score, params
    return best_params, best_score

haar-cascade.pseudocode:
def integral(img):  # ii[y][x] = 왼쪽 위 영역 합
    h, w = len(img), len(img[0])
    ii = [[0] * (w + 1) for _ in range(h + 1)]
    for y in range(h):
        for x in range(w):
            ii[y + 1][x + 1] = (img[y][x] + ii[y][x + 1]
                                + ii[y + 1][x] - ii[y][x])
    return ii

def rect_sum(ii, x, y, w, h):  # 4번 참조로 O(1)
    return (ii[y + h][x + w] - ii[y][x + w]
            - ii[y + h][x] + ii[y][x])

def cascade(window, stages):
    for stage in stages:  # 단계별 강분류기
        if stage.score(window) < stage.threshold:
            return False  # 조기 기각 → 고속
    return True  # 모든 단계 통과 → 얼굴

hamiltonian-path-problem.pseudocode:
def has_hamiltonian_path(n, adj):
    # n 정점, adj[u] = u의 이웃 집합. 백트래킹 (지수)
    def backtrack(v, visited):
        if len(visited) == n:  # 모든 정점 방문
            return True
        for w in adj[v]:
            if w not in visited:
                visited.add(w)
                if backtrack(w, visited):
                    return True
                visited.remove(w)  # 되돌리기
        return False

    return any(backtrack(s, {s}) for s in range(n))

hard-link.pseudocode:
def link(fs, src, dst):
    ino = fs.lookup(src)  # 원본의 inode
    if ino.is_dir:
        raise OSError('디렉터리 하드 링크 금지')  # 순환 방지
    if fs.device(dst) != ino.device:
        raise OSError('EXDEV: 다른 파일시스템')
    fs.add_entry(dst, ino.number)  # 새 이름 → 같은 inode
    ino.nlink += 1

def unlink(fs, path):
    ino = fs.lookup(path)
    fs.remove_entry(path)
    ino.nlink -= 1
    if ino.nlink == 0 and ino.open_count == 0:
        fs.free(ino)  # 블록·inode 반납

harmonic-mean.pseudocode:
def harmonic_mean(values):
    n = len(values)
    return n / sum(1.0 / x for x in values)

def f1_score(precision, recall):
    if precision + recall == 0:
        return 0.0
    # 정밀도·재현율의 조화평균
    return 2 * precision * recall / (precision + recall)

# 예: P=1.0, R=0.0 → F1=0 (낮은 쪽에 끌림)
# P=0.6, R=0.6 → F1=0.6

hash-based-signature.pseudocode:
def keygen():  # Lamport 일회용 서명 (256비트)
    sk = [[rand256(), rand256()] for _ in range(256)]
    pk = [[H(a), H(b)] for a, b in sk]
    return sk, pk

def sign(sk, msg):
    d = bits(H(msg))  # 다이제스트 256비트
    return [sk[i][d[i]] for i in range(256)]  # 비트별 공개

def verify(pk, msg, sig):
    d = bits(H(msg))
    return all(H(sig[i]) == pk[i][d[i]]
               for i in range(256))

# 같은 키로 두 번 서명하면 비밀 절반 이상 노출 → 위조
# 머클 트리(XMSS)로 다수 일회용 키를 하나의 공개키로 묶음

hash-collision.pseudocode:
def lp_insert(table, key, h):  # 선형 조사 개방 주소법
    m = len(table)
    for step in range(m):
        j = (h(key) + step) % m  # 충돌 시 다음 칸
        if table[j] is None or table[j] == key:
            table[j] = key
            return j
    raise OverflowError('테이블 가득 참')

def lp_search(table, key, h):
    m = len(table)
    for step in range(m):
        j = (h(key) + step) % m
        if table[j] is None:
            return -1  # 빈 칸 도달 → 키 없음
        if table[j] == key:
            return j
    return -1

hash-join.pseudocode:
def hash_join(build, probe, bkey, pkey):
    # 1) Build: 작은 입력으로 메모리 해시 테이블 생성
    table = {}
    for r in build:
        table.setdefault(r[bkey], []).append(r)
    # 2) Probe: 큰 입력을 한 번 스캔하며 등치 매칭
    for s in probe:
        for r in table.get(s[pkey], []):
            yield {**r, **s}

def grace_hash_join(build, probe, bkey, pkey, n):
    # 메모리 초과 시: 같은 해시로 n개 파티션 분할
    bp = [[] for _ in range(n)]
    pp = [[] for _ in range(n)]
    for r in build:
        bp[hash(r[bkey]) % n].append(r)
    for s in probe:
        pp[hash(s[pkey]) % n].append(s)
    for i in range(n):  # 같은 번호 파티션끼리만 조인
        yield from hash_join(bp[i], pp[i], bkey, pkey)

header-node.pseudocode:
class Node:
    def __init__(self, data=None):
        self.data, self.next = data, None

def make_list():
    return Node()  # 헤더 노드: 데이터 없음

def insert_front(head, x):
    node = Node(x)
    node.next = head.next  # 공백 리스트여도 동일 코드
    head.next = node

def delete(head, x):
    prev = head  # 첫 노드 삭제도 특례 없음
    while prev.next and prev.next.data != x:
        prev = prev.next
    if prev.next:
        prev.next = prev.next.next

heap-sort.pseudocode:
def sift_down(A, i, n):
    while 2 * i + 1 < n:
        c = 2 * i + 1  # 왼쪽 자식
        if c + 1 < n and A[c + 1] > A[c]:
            c += 1  # 더 큰 자식 선택
        if A[i] >= A[c]:
            break  # 힙 성질 만족
        A[i], A[c] = A[c], A[i]
        i = c

def heap_sort(A):
    n = len(A)
    for i in range(n // 2 - 1, -1, -1):
        sift_down(A, i, n)  # Build-Max-Heap: O(n)
    for end in range(n - 1, 0, -1):
        A[0], A[end] = A[end], A[0]  # 최댓값을 끝으로
        sift_down(A, 0, end)  # 줄어든 힙 복원
    return A

heapify.pseudocode:
def sift_down(A, i, n):  # 최대 힙, O(log n)
    while True:
        l, r = 2 * i + 1, 2 * i + 2
        big = i
        if l < n and A[l] > A[big]:
            big = l
        if r < n and A[r] > A[big]:
            big = r
        if big == i:  # 부모가 가장 큼 → 종료
            return
        A[i], A[big] = A[big], A[i]
        i = big  # 교환한 자식 위치로 내려감

def build_heap(A):  # 전체 O(n)
    n = len(A)
    for i in range(n // 2 - 1, -1, -1):  # 마지막 내부 노드부터
        sift_down(A, i, n)

heuristic-miner.pseudocode:
def heuristic_miner(log, threshold=0.9):
    # log: [['a', 'b', 'c'], ['a', 'c', 'b'], ...]
    follows = {}  # (a, b): a 바로 뒤 b가 나온 횟수
    for trace in log:
        for a, b in zip(trace, trace[1:]):
            follows[(a, b)] = follows.get((a, b), 0) + 1
    acts = {x for t in log for x in t}
    edges = {}
    for a in acts:
        for b in acts:
            ab = follows.get((a, b), 0)
            ba = follows.get((b, a), 0)
            if a == b:
                dep = ab / (ab + 1)  # 길이 1 루프
            else:
                dep = (ab - ba) / (ab + ba + 1)  # -1~1
            if dep >= threshold:  # 빈도 낮은 노이즈 제거
                edges[(a, b)] = dep
    return edges  # 의존 그래프의 간선

hidden-surface-removal.pseudocode:
def z_buffer(polygons, W, H):
    depth = [[INF] * W for _ in range(H)]  # 깊이 버퍼
    frame = [[BG] * W for _ in range(H)]  # 색 버퍼
    for poly in polygons:
        # 다각형이 덮는 픽셀과 그 점의 깊이 z
        for x, y, z in rasterize(poly):
            if z < depth[y][x]:  # 더 가까우면 갱신
                depth[y][x] = z
                frame[y][x] = shade(poly, x, y)
    return frame  # 그리는 순서와 무관

hierarchical-clustering.pseudocode:
def agglomerative(points, dist, linkage):
    clusters = [[p] for p in points]  # 각 점이 군집
    merges = []
    while len(clusters) > 1:
        best, pair = None, None
        for i in range(len(clusters)):
            for j in range(i + 1, len(clusters)):
                d = linkage(clusters[i], clusters[j], dist)
                if best is None or d < best:
                    best, pair = d, (i, j)
        i, j = pair  # 가장 가까운 두 군집 병합
        merges.append((clusters[i], clusters[j], best))
        clusters[i] = clusters[i] + clusters[j]
        del clusters[j]
    return merges  # 병합 순서 = 덴드로그램

hierarchical-navigable-small-world.pseudocode:
def hnsw_search(q, ep, top, ef, k):
    for lc in range(top, 0, -1):  # 상위 희소층: 탐욕 하강
        ep = search_layer(q, ep, 1, lc)[0]
    return search_layer(q, ep, ef, 0)[:k]  # 0층: ef개 탐색

def search_layer(q, ep, ef, lc):
    d = lambda v: dist(q, v)
    visited, cand, best = {ep}, [ep], [ep]
    while cand:
        c = min(cand, key=d)  # 가장 가까운 후보 확장
        cand.remove(c)
        if d(c) > d(best[-1]):  # best는 거리순 유지
            break  # 더 가까워질 수 없음 → 종료
        for nb in neighbors(c, lc):
            if nb in visited:
                continue
            visited.add(nb)
            if len(best) < ef or d(nb) < d(best[-1]):
                cand.append(nb)
                best = sorted(best + [nb], key=d)[:ef]
    return best  # 거리순 상위 ef개

hill-climbing.pseudocode:
def hill_climbing(start, neighbors, score):
    current = start
    while True:
        # 이웃 중 평가값 최대 선택
        best = max(neighbors(current), key=score,
                   default=None)
        if best is None or score(best) <= score(current):
            return current  # 더 나은 이웃 없음 → 정지
        current = best  # 더 좋은 이웃으로만 이동

hkdf.pseudocode:
def hkdf_extract(salt, ikm):
    if not salt:
        salt = bytes(HASH_LEN)  # 솔트 없으면 0으로 채움
    return hmac(salt, ikm)  # PRK

def hkdf_expand(prk, info, length):
    n = ceil(length / HASH_LEN)  # 최대 255블록
    t, okm = b'', b''
    for i in range(1, n + 1):
        # T(i) = HMAC(PRK, T(i-1) ‖ info ‖ i)
        t = hmac(prk, t + info + bytes([i]))
        okm += t
    return okm[:length]

hybrid-quantum-classical-algorithm.pseudocode:
def vqe(ansatz, hamiltonian, optimizer, theta, n_iter):
    # ansatz: 매개변수 양자회로, optimizer: 고전 최적화
    for _ in range(n_iter):
        def cost(t):
            state = ansatz.run(t)  # 양자 회로 실행
            return measure_expectation(state, hamiltonian)
        energy = cost(theta)
        # 고전 옵티마이저가 파라미터 갱신 (기울기·무기울기)
        theta = optimizer.step(cost, theta)
    return theta, energy  # 근사 바닥상태 에너지

hybrid-search.pseudocode:
def reciprocal_rank_fusion(rankings, k=60):
    # rankings: 각 검색기의 순위 리스트 [문서ID...]
    scores = {}
    for ranking in rankings:
        for rank, doc in enumerate(ranking):
            # 순위가 높을수록(작을수록) 큰 점수
            prev = scores.get(doc, 0)
            scores[doc] = prev + 1 / (k + rank)
    return sorted(scores, key=scores.get, reverse=True)

hypercube-topology.pseudocode:
def ecube_route(src, dst, n):
    # n차원 하이퍼큐브: 낮은 비트부터 다른 비트 교정
    path, cur = [src], src
    for i in range(n):
        if (cur ^ dst) >> i & 1:  # i번째 비트가 다르면
            cur ^= 1 << i  # 차원 i 링크로 이동
            path.append(cur)
    return path  # 홉 수 = 해밍 거리 ≤ n(지름)

hyperparameter-optimization.pseudocode:
# 랜덤 탐색 + K-겹 교차검증 (블랙박스 최적화)
def random_search(space, n_trials, data, k=5):
    best, best_score = None, float('-inf')
    for _ in range(n_trials):
        # 각 하이퍼파라미터를 분포에서 무작위 샘플
        lam = {name: sample(dist)
               for name, dist in space.items()}
        score = cross_val_score(lam, data, k)  # 목적함수
        if score > best_score:
            best, best_score = lam, score
    return best, best_score

