introsort.pseudocode:
def introsort(a):
    if len(a) > 1:
        depth = 2 * floor(log2(len(a)))  # 재귀 깊이 한계
        intro(a, 0, len(a) - 1, depth)

def intro(a, lo, hi, depth):
    if hi - lo + 1 <= 16:
        insertion_sort(a, lo, hi)  # 소구간
        return
    if depth == 0:
        heap_sort(a, lo, hi)  # 퀵 퇴화 → 힙 정렬 전환
        return
    p = partition(a, lo, hi)  # 퀵 정렬 분할
    intro(a, lo, p - 1, depth - 1)
    intro(a, p + 1, hi, depth - 1)

inverted-index.pseudocode:
def build_index(docs):  # docs: {문서ID: 텍스트}
    index = {}  # 단어 → {문서ID: [출현 위치]}
    for doc_id in sorted(docs):
        for pos, term in enumerate(tokenize(docs[doc_id])):
            postings = index.setdefault(term, {})
            postings.setdefault(doc_id, []).append(pos)
    return index

def intersect(p1, p2):  # 정렬된 게시 목록 AND (병합)
    i = j = 0
    out = []
    while i < len(p1) and j < len(p2):
        if p1[i] == p2[j]:
            out.append(p1[i])
            i += 1
            j += 1
        elif p1[i] < p2[j]:
            i += 1
        else:
            j += 1
    return out  # O(len(p1) + len(p2))

inverted-page-table.pseudocode:
def translate(pid, vaddr, ipt, anchor, page_size):
    p, d = divmod(vaddr, page_size)
    # 해시 앵커 테이블 → 해당 체인의 첫 프레임
    i = anchor[hash((pid, p)) % len(anchor)]
    while i is not None:
        entry = ipt[i]  # 프레임 i를 소유한 (pid, page)
        if entry.pid == pid and entry.page == p:
            return i * page_size + d  # 인덱스 = 프레임 번호
        i = entry.next  # 해시 충돌 체인 따라가기
    raise PageFault(pid, p)

ioc-container.pseudocode:
class Container:
    def __init__(self, defs):
        self.defs = defs  # 이름 → (클래스, 의존 빈 이름들)
        self.singletons = {}

    def get(self, name):
        if name in self.singletons:  # 싱글톤 스코프 재사용
            return self.singletons[name]
        cls, deps = self.defs[name]
        # 의존 빈을 먼저 재귀 생성 (그래프 순서)
        args = [self.get(d) for d in deps]
        bean = cls(*args)  # 생성자 주입
        self.singletons[name] = bean
        return bean

isolation-forest.pseudocode:
def c(n):  # 크기 n의 평균 경로 길이 (정규화 상수)
    if n <= 1:
        return 0.0
    return 2 * (log(n - 1) + 0.5772) - 2 * (n - 1) / n

def build_itree(X, d, max_d):  # d: 현재 깊이
    if d >= max_d or len(X) <= 1:
        return Leaf(size=len(X))
    q = random_feature(X)  # 무작위 속성
    p = random_uniform(min_of(X, q), max_of(X, q))
    L = [x for x in X if x[q] < p]  # 무작위 분할값 p
    R = [x for x in X if x[q] >= p]
    return Node(q, p, build_itree(L, d + 1, max_d),
                build_itree(R, d + 1, max_d))

def path_length(x, node, d=0):
    if node.is_leaf:
        return d + c(node.size)  # 미분할 잔여 점 보정
    nxt = node.left if x[node.q] < node.p else node.right
    return path_length(x, nxt, d + 1)

def score(x, trees, psi):  # 1에 가까울수록 이상치
    E = mean(path_length(x, t) for t in trees)
    return 2 ** (-E / c(psi))

