class BookShelf:  # ConcreteAggregate
    def __init__(self):
        self.books = []
    def create_iterator(self):
        return ShelfIterator(self)

class ShelfIterator:  # ConcreteIterator
    def __init__(self, shelf):
        self.shelf = shelf
        self.index = 0  # 순회 상태는 반복자가 보유
    def has_next(self):
        return self.index < len(self.shelf.books)
    def next(self):
        item = self.shelf.books[self.index]
        self.index += 1
        return item

