k-anonymity.pseudocode:
def is_k_anonymous(rows, qi, k):
    groups = {}
    for r in rows:
        key = tuple(r[a] for a in qi)  # 준식별자 조합
        groups[key] = groups.get(key, 0) + 1
    return min(groups.values()) >= k  # 최소 클래스 크기

def is_l_diverse(rows, qi, sensitive, l):  # 보완 모델
    groups = {}
    for r in rows:
        key = tuple(r[a] for a in qi)
        groups.setdefault(key, set()).add(r[sensitive])
    return all(len(v) >= l for v in groups.values())

k-nearest-neighbor.pseudocode:
def knn_predict(train, x, k, mode='class'):
    # train: [(특징 벡터, 레이블 또는 값), ...]
    dists = []
    for feat, y in train:
        d = sum((a - b) ** 2 for a, b in zip(feat, x))
        dists.append((d ** 0.5, y))  # 유클리드 거리
    dists.sort(key=lambda t: t[0])  # 가까운 순
    top = dists[:k]
    if mode == 'class':  # 다수결
        votes = {}
        for _, y in top:
            votes[y] = votes.get(y, 0) + 1
        return max(votes, key=votes.get)
    if mode == 'wknn':  # 거리 역수 가중 평균
        w = [1 / (d + 1e-9) for d, _ in top]
        num = sum(wi * y for wi, (_, y) in zip(w, top))
        return num / sum(w)
    return sum(y for _, y in top) / k  # 회귀: 평균

k-nearest-neighbors.pseudocode:
# train: [(특징 벡터, 레이블)], 스케일링 완료 가정
def knn_predict(train, x, k, task='classify'):
    dists = sorted((dist(x, xi), yi) for xi, yi in train)
    neighbors = [y for _, y in dists[:k]]  # 최근접 k개
    if task == 'classify':
        votes = {}
        for y in neighbors:  # 다수결 투표
            votes[y] = votes.get(y, 0) + 1
        return max(votes, key=votes.get)
    return sum(neighbors) / k  # 회귀: 평균

kd-tree.pseudocode:
def build(points, depth=0, k=2):
    if not points:
        return None
    axis = depth % k  # 레벨마다 축 순환
    points = sorted(points, key=lambda p: p[axis])
    m = len(points) // 2  # 중앙값 분할
    return Node(points[m], axis,
                build(points[:m], depth + 1, k),
                build(points[m + 1:], depth + 1, k))

def nearest(node, q, best=None):
    if node is None:
        return best
    if best is None or dist(q, node.point) < dist(q, best):
        best = node.point
    diff = q[node.axis] - node.point[node.axis]
    if diff < 0:
        near, far = node.left, node.right
    else:
        near, far = node.right, node.left
    best = nearest(near, q, best)
    if abs(diff) < dist(q, best):  # 분할면 너머 확인
        best = nearest(far, q, best)
    return best

kernel-trick.pseudocode:
def kernel(x, z, kind='rbf', gamma=0.5, deg=3):
    if kind == 'linear':
        return dot(x, z)
    if kind == 'poly':  # (x·z + 1)^d
        return (dot(x, z) + 1) ** deg
    if kind == 'rbf':  # exp(-γ‖x-z‖²)
        diff = [a - b for a, b in zip(x, z)]
        return exp(-gamma * dot(diff, diff))

def decision(x, sv, alpha, y, b, kind='rbf'):
    # φ 계산 없이 커널 내적만으로 판별
    s = b
    for i in range(len(sv)):
        s += alpha[i] * y[i] * kernel(sv[i], x, kind)
    return 1 if s >= 0 else -1

key-stretching.pseudocode:
def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def pbkdf2_block(prf, pw, salt, c, i):
    u = prf(pw, salt + i.to_bytes(4, 'big'))  # U1
    t = u
    for _ in range(c - 1):  # c회 반복 → 공격 비용 c배
        u = prf(pw, u)  # Uj = PRF(pw, Uj-1)
        t = xor_bytes(t, u)  # 모든 중간값 XOR 누적
    return t

def pbkdf2(prf, pw, salt, c, dk_len, h_len):
    n_blocks = -(-dk_len // h_len)  # 올림 나눗셈
    dk = b''
    for i in range(1, n_blocks + 1):
        dk += pbkdf2_block(prf, pw, salt, c, i)
    return dk[:dk_len]

keyframe-animation.pseudocode:
def interpolate(key_a, key_b, t):
    # key = (time, value), t: 현재 시각
    span = key_b[0] - key_a[0]
    if span == 0:
        return key_a[1]
    r = (t - key_a[0]) / span  # 0~1 보간 비율
    r = ease_in_out(r)  # F-Curve로 가감속
    return key_a[1] + (key_b[1] - key_a[1]) * r

def ease_in_out(r):  # 스무스스텝(감속·가속)
    return r * r * (3 - 2 * r)

knapsack-problem.pseudocode:
def knapsack_01(weights, values, W):
    dp = [0] * (W + 1)  # dp[w]: 용량 w의 최대 가치
    for wi, vi in zip(weights, values):
        # 역순 순회: 물건을 한 번만 사용(0/1)
        for w in range(W, wi - 1, -1):
            dp[w] = max(dp[w], dp[w - wi] + vi)
    return dp[W]

def knapsack_fractional(items, W):  # items: (무게, 가치)
    items.sort(key=lambda x: x[1] / x[0], reverse=True)
    total = 0
    for wi, vi in items:
        if W <= 0:
            break
        take = min(wi, W)  # 남은 용량만큼 쪼개서 담음
        total += vi * take / wi
        W -= take
    return total

