def schedule(pod, nodes):
    # 1단계: 필터링(실행 불가 노드 제외)
    feasible = []
    for n in nodes:
        if fits_resources(pod, n) and \
           tolerates(pod, n) and affinity_ok(pod, n):
            feasible.append(n)
    if not feasible:
        return None  # 스케줄 불가(Pending)
    # 2단계: 스코어링(적합도 최고 노드 선택)
    best, best_score = None, -1
    for n in feasible:
        s = score(pod, n)  # 0~100
        if s > best_score:
            best, best_score = n, s
    return best  # 바인딩 대상

lagrange-basis-polynomial.pseudocode:
def basis(xs, i, x):
    L = 1.0
    for j in range(len(xs)):
        if j != i:  # j = i 항은 제외한 곱
            L *= (x - xs[j]) / (xs[i] - xs[j])
    return L  # xs[i]에서 1, 다른 xs[j]에서 0

def interpolate(xs, ys, x):
    # P(x) = Σ yi · Li(x)
    return sum(ys[i] * basis(xs, i, x)
               for i in range(len(xs)))

laplace-mechanism.pseudocode:
def laplace_noise(b):
    # 역변환 샘플링: u ~ Uniform(-0.5, 0.5)
    u = uniform(-0.5, 0.5)
    return -b * sign(u) * log(1 - 2 * abs(u))

def laplace_mechanism(true_answer, sensitivity, epsilon):
    b = sensitivity / epsilon  # 잡음 규모 Δf/ε
    return true_answer + laplace_noise(b)

# 예: 개수 질의 Δf = 1, ε = 0.5 → b = 2
# noisy = laplace_mechanism(count, 1, 0.5)

