def momentum_update(theta, grad, v, lr, beta=0.9):
    # v: 속도(과거 기울기의 지수이동평균)
    for j in range(len(theta)):
        v[j] = beta * v[j] + grad[j]  # 관성 누적
        theta[j] -= lr * v[j]  # 속도 방향으로 이동
    return theta, v

monitor-synchronization.pseudocode:
class BoundedBuffer:  # 모니터: 진입 상호배제는 런타임이 보장
    def __init__(self, n):
        self.buf, self.n = [], n
        self.not_full = Condition()  # 조건 변수
        self.not_empty = Condition()

    @synchronized  # 한 번에 한 스레드만 진입
    def put(self, item):
        while len(self.buf) == self.n:  # Mesa: while 재검사
            self.not_full.wait()  # 모니터 락 반납 후 대기
        self.buf.append(item)
        self.not_empty.signal()  # 대기 중 소비자 1개 깨움

    @synchronized
    def get(self):
        while not self.buf:
            self.not_empty.wait()
        item = self.buf.pop(0)
        self.not_full.signal()
        return item

monkey-testing.pseudocode:
def monkey_test(app, n_events, seed):
    rng = Random(seed)  # 시드 고정 → 같은 이벤트열 재현
    log = []
    for i in range(n_events):
        ev = rng.choice(['tap', 'swipe', 'key', 'back'])
        x, y = rng.randint(0, 1079), rng.randint(0, 1919)
        log.append((i, ev, x, y))
        try:
            app.inject(ev, x, y)
        except AppCrash:
            return 'crash', seed, log  # 시드·로그로 재현
    return 'pass', seed, log

monte-carlo-tree-search.pseudocode:
def mcts(root, budget, c=1.41):
    for _ in range(budget):
        node = root
        while node.children and not node.untried:
            node = best_ucb(node, c)  # 선택
        if node.untried:  # 확장
            node = node.expand()
        result = rollout(node.state)  # 무작위 시뮬레이션
        while node:  # 역전파
            node.visits += 1
            node.wins += result
            node = node.parent
    return max(root.children, key=lambda n: n.visits)

def best_ucb(node, c):
    import math
    def score(ch):
        exploit = ch.wins / ch.visits
        lnN = math.log(node.visits)
        explore = c * math.sqrt(lnN / ch.visits)
        return exploit + explore  # 탐험·활용 균형
    return max(node.children, key=score)

multi-armed-bandit.pseudocode:
def ucb_select(counts, values, t, c=2):
    import math
    n = len(counts)
    for i in range(n):
        if counts[i] == 0:
            return i  # 미시도 암 우선
    def ucb(i):
        avg = values[i]  # 추정 평균 보상
        bonus = c * math.sqrt(math.log(t) / counts[i])
        return avg + bonus  # 활용 + 탐색 보너스
    return max(range(n), key=ucb)

def update(counts, values, arm, reward):
    counts[arm] += 1
    n = counts[arm]
    # 증분 평균 갱신
    values[arm] += (reward - values[arm]) / n

multi-version-concurrency-control.pseudocode:
def visible(v, snap):  # snap: 스냅샷 정보
    c, d = v.created_by, v.deleted_by
    if c != snap.my_tx:
        if c >= snap.xmax or c in snap.active:
            return False  # 스냅샷 이후·진행 중 생성
        if not committed(c):
            return False  # 철회된 생성
    if d is None:
        return True
    if d == snap.my_tx:
        return False  # 내가 삭제함
    if d >= snap.xmax or d in snap.active:
        return True  # 삭제가 아직 안 보임
    return not committed(d)  # 철회된 삭제면 보임

def read(row, snap):  # 잠금 없이 읽기
    v = row.newest
    while v is not None and not visible(v, snap):
        v = v.prev  # 이전 버전으로 이동
    return v

multipoint-relay.pseudocode:
def select_mpr(n1, n2_of):
    # n1: 1홉 이웃, n2_of[v]: v로 닿는 2홉 이웃(자신 제외)
    two_hop = set().union(*(n2_of[v] for v in n1)) - n1
    mpr, covered = set(), set()
    # 1) 한 이웃으로만 닿는 2홉이 있으면 그 이웃 필수
    for t in two_hop:
        via = [v for v in n1 if t in n2_of[v]]
        if len(via) == 1:
            mpr.add(via[0])
    for v in mpr:
        covered |= n2_of[v]
    # 2) 남은 2홉을 가장 많이 덮는 이웃부터 탐욕 선택
    while two_hop - covered:
        rest = two_hop - covered
        gain = lambda v: len(n2_of[v] & rest)
        best = max(n1 - mpr, key=gain)
        mpr.add(best)
        covered |= n2_of[best]
    return mpr

# n2_of = {A: {X, Y}, B: {Y, W}, C: {W, Z}} → {A, C}

mutant.pseudocode:
def mutation_score(program, operators, tests, is_equiv):
    # 전제: 모든 테스트가 원본 program에서 통과
    killed = total = 0
    for op in operators:
        for mutant in op.apply_once(program):
            if is_equiv(mutant):  # 동등 뮤턴트 제외
                continue
            total += 1
            for t in tests:
                if not t.passes(mutant):  # 실패 = 탐지
                    killed += 1
                    break
    return killed / total if total else 1.0

n-version-programming.pseudocode:
def nvp_execute(versions, x):
    results = []
    for v in versions:  # 독립 개발된 N개 버전 실행
        try:
            results.append(v(x))
        except Exception:
            results.append(None)  # 실패한 버전
    counts = {}
    for r in results:
        if r is not None:
            counts[r] = counts.get(r, 0) + 1
    if not counts:
        raise RuntimeError('전 버전 실패')
    best = max(counts, key=counts.get)
    if counts[best] > len(versions) // 2:  # 과반 일치
        return best
    raise RuntimeError('합의 실패')  # 안전 상태로 전환

naive-bayes-classifier.pseudocode:
def train_nb(docs, labels, alpha=1):
    vocab = {w for d in docs for w in d}
    prior, likelihood = {}, {}
    for c in set(labels):
        dc = [d for d, y in zip(docs, labels) if y == c]
        prior[c] = len(dc) / len(docs)  # P(C)
        counts = word_counts(dc)
        total = sum(counts.values())
        # 라플라스 스무딩: 처음 보는 단어도 확률 > 0
        likelihood[c] = {w: (counts.get(w, 0) + alpha)
                         / (total + alpha * len(vocab))
                         for w in vocab}
    return prior, likelihood

def predict_nb(doc, prior, likelihood):
    best, best_score = None, float('-inf')
    for c in prior:  # 로그 합으로 언더플로 방지
        s = log(prior[c])
        s += sum(log(likelihood[c][w])
                 for w in doc if w in likelihood[c])
        if s > best_score:  # 최대 사후확률(MAP)
            best, best_score = c, s
    return best

