nccl.pseudocode:
def ring_all_reduce(bufs):
    # bufs[r]: GPU r의 텐서를 N개 청크로 나눈 리스트
    N = len(bufs)
    # 1단계 Reduce-Scatter: N-1 스텝 (GPU 동시 송신)
    for s in range(N - 1):
        for r in range(N):
            c = (r - s) % N  # GPU r이 이번에 보낼 청크
            bufs[(r + 1) % N][c] += bufs[r][c]
    # 이 시점 GPU r은 청크 (r+1)%N 의 전체 합 보유
    # 2단계 All-Gather: N-1 스텝으로 완성 청크 전파
    for s in range(N - 1):
        for r in range(N):
            c = (r + 1 - s) % N
            bufs[(r + 1) % N][c] = bufs[r][c]
    return bufs  # 모든 GPU가 동일한 합계 보유

# GPU당 전송량 2(N-1)/N × 데이터 → GPU 수와 거의 무관

ndcg.pseudocode:
def dcg(rels, k):
    # 순위 i(1부터)의 관련도를 log2(i+1)로 할인
    return sum(rel / log2(i + 1)
               for i, rel in enumerate(rels[:k], start=1))

def ndcg(ranked_rels, k):
    # 이상 순위: 관련도 내림차순 정렬 (최대 DCG)
    ideal = sorted(ranked_rels, reverse=True)
    idcg = dcg(ideal, k)
    return dcg(ranked_rels, k) / idcg if idcg > 0 else 0.0

# 관련도 [3, 2, 3, 0, 1]
# DCG ≈ 6.149, IDCG ≈ 6.323 → nDCG@5 ≈ 0.972

nearest-neighbor-search.pseudocode:
def knn(root, q, k):
    pq = MinHeap([(0, root)])  # (하한 거리, 노드·객체)
    result = []
    while pq and len(result) < k:
        d, e = pq.pop()  # 하한이 가장 작은 항목
        if e.is_object:
            result.append((d, e))  # 꺼낸 객체는 확정
        else:
            for c in e.children:
                # 노드는 MINDIST, 객체는 실제 거리
                pq.push((mindist(q, c), c))
    return result

negative-cycle.pseudocode:
def has_negative_cycle(V, edges, src):
    INF = float('inf')
    dist = [INF] * V
    dist[src] = 0
    for _ in range(V - 1):  # V-1회 반복 완화
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    for u, v, w in edges:  # V번째 반복: 검사만
        if dist[u] != INF and dist[u] + w < dist[v]:
            return True  # 여전히 갱신됨 → 음수 사이클
    return False  # src에서 도달 가능한 음수 사이클 없음

