def nested_loop_join(outer, inner_index, cond):
    for r in outer:  # 선행(드라이빙) 테이블 행
        if not cond(r):
            continue  # 선행 필터 먼저 적용
        # 후행: 조인 키 인덱스로 랜덤 액세스
        for s in inner_index.lookup(r.key):
            yield r + s  # 즉시 반환 → 부분범위 처리
# 인덱스 없으면 inner 전체 스캔 반복 → O(N×M)

net-present-value.pseudocode:
def npv(rate, cashflows, initial):
    pv = 0
    for t, cf in enumerate(cashflows, start=1):
        pv += cf / (1 + rate) ** t  # 미래 현금흐름 할인
    return pv - initial

def irr(cashflows, initial, lo=-0.99, hi=1.0, eps=1e-6):
    # NPV(r) = 0인 r을 이분 탐색 (일반형 현금흐름 가정)
    while hi - lo > eps:
        mid = (lo + hi) / 2
        if npv(mid, cashflows, initial) > 0:
            lo = mid  # 아직 양수 → 할인율 상향
        else:
            hi = mid
    return (lo + hi) / 2

# npv(0.1, [500, 500, 500], 1000) → 243.4 (채택)

non-blocking-algorithm.pseudocode:
class LockFreeStack:  # Treiber 스택
    def __init__(self):
        self.top = AtomicRef(None)

    def push(self, value):
        node = Node(value)
        while True:
            old = self.top.load()
            node.next = old
            # 그 사이 top이 안 바뀌었을 때만 교체
            if self.top.cas(old, node):
                return

    def pop(self):
        while True:
            old = self.top.load()
            if old is None:
                return None
            # ABA 방지: 태그 포인터·해저드 포인터 필요
            if self.top.cas(old, old.next):
                return old.value
            # 실패 → 다른 스레드가 진행한 것 → 재시도

