optimal-page-replacement.pseudocode:
def opt(refs, capacity):
    frames, faults = [], 0
    for i, page in enumerate(refs):
        if page in frames:
            continue  # 적중
        faults += 1
        if len(frames) < capacity:
            frames.append(page)
            continue

        def next_use(p):  # 다음 참조 위치(없으면 무한대)
            for j in range(i + 1, len(refs)):
                if refs[j] == p:
                    return j
            return float('inf')

        victim = max(frames, key=next_use)  # 가장 늦게 쓰일
        frames[frames.index(victim)] = page
    return faults

orthogonal-frequency-division-multiplexi.pseudocode:
def ofdm_tx(bits, n_sub, cp_len):
    syms = qam_map(bits)  # 비트 → 복소 심볼
    out = []
    for i in range(0, len(syms), n_sub):
        X = syms[i:i + n_sub]  # 부반송파마다 1심볼(병렬)
        x = ifft(X)  # 주파수 → 시간 영역
        out += x[-cp_len:] + x  # CP: 꼬리를 앞에 복사
    return out

def ofdm_rx(samples, n_sub, cp_len):
    syms, step = [], n_sub + cp_len
    for i in range(0, len(samples), step):
        y = samples[i + cp_len:i + step]  # CP 제거
        Y = fft(y)
        syms += equalize(Y)  # 부반송파별 1탭 등화
    return qam_demap(syms)

