otp.pseudocode:
import hmac, hashlib, struct, time

def hotp(key, counter, digits=6):
    msg = struct.pack('>Q', counter)  # 8바이트 카운터
    mac = hmac.new(key, msg, hashlib.sha1).digest()
    off = mac[-1] & 0x0F  # 동적 절단 오프셋
    code = struct.unpack('>I', mac[off:off + 4])[0]
    code &= 0x7FFFFFFF  # 최상위 비트 제거
    return code % (10 ** digits)

def totp(key, step=30, digits=6):
    counter = int(time.time() // step)  # 시간 → 카운터
    return hotp(key, counter, digits)

out-of-bag-error.pseudocode:
def oob_error(data, B, train):
    n = len(data)
    votes = {i: [] for i in range(n)}
    for _ in range(B):
        idx = [randint(0, n - 1) for _ in range(n)]  # 복원추출
        model = train([data[i] for i in idx])
        inbag = set(idx)
        for i in range(n):
            if i not in inbag:  # 학습에 안 쓰인 표본만 평가
                votes[i].append(model.predict(data[i].x))
    wrong = total = 0
    for i, v in votes.items():
        if v:  # 한 번이라도 OOB였던 관측치
            total += 1
            wrong += majority(v) != data[i].y
    return wrong / total

overlapping-subproblems.pseudocode:
def fib_naive(n):  # 중복 호출로 O(2^n)
    if n <= 1:
        return n
    return fib_naive(n - 1) + fib_naive(n - 2)

def fib_memo(n, memo):  # 하향식 메모이제이션 O(n)
    if n <= 1:
        return n
    if n not in memo:  # 부분 문제는 1회만 계산
        a = fib_memo(n - 1, memo)
        memo[n] = a + fib_memo(n - 2, memo)
    return memo[n]

def fib_tab(n):  # 상향식 타뷸레이션 O(n)
    dp = [0, 1] + [0] * max(0, n - 1)
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

page-table.pseudocode:
def translate(vaddr, cr3, user_mode, write):
    idx = [(vaddr >> s) & 0x1FF for s in (39, 30, 21, 12)]
    table = cr3  # PML4 테이블 물리 주소
    for i in idx:  # PML4 → PDPT → PD → PT
        entry = read_phys(table + i * 8)
        if not entry.present:
            raise PageFault(vaddr)
        if user_mode and not entry.user:
            raise PageFault(vaddr)  # U/S: 커널 페이지 보호
        if write and not entry.writable:
            raise PageFault(vaddr)  # R/W 위반
        table = entry.frame_addr  # 다음 단계 테이블
    return table + (vaddr & 0xFFF)  # 프레임 + 오프셋

pagerank.pseudocode:
def pagerank(graph, d=0.85, eps=1e-6):
    # graph: {노드: [링크 대상 노드 목록]}
    nodes = list(graph)
    n = len(nodes)
    pr = {v: 1 / n for v in nodes}
    while True:
        new = {v: (1 - d) / n for v in nodes}  # 임의 이동
        for v in nodes:
            out = graph[v]
            if out:
                for w in out:
                    new[w] += d * pr[v] / len(out)
            else:  # 나가는 링크 없음: 전체에 균등 분배
                for w in nodes:
                    new[w] += d * pr[v] / n
        diff = sum(abs(new[v] - pr[v]) for v in nodes)
        pr = new
        if diff < eps:  # 수렴 판정
            return pr

parameter-efficient-fine-tuning.pseudocode:
class LoRALinear:
    def __init__(self, W0, r, alpha):
        self.W0 = W0  # 사전학습 가중치 d×k, 고정
        d, k = shape(W0)
        self.A = randn(r, k) * 0.01  # 학습 대상
        self.B = zeros(d, r)  # 0 초기화: 시작 시 ΔW=0
        self.scale = alpha / r
    def forward(self, x):
        base = self.W0 @ x
        delta = self.B @ (self.A @ x)  # 저차 경로
        return base + self.scale * delta
    def trainable(self):
        return [self.A, self.B]  # r·(d+k)개만 학습
    def merge(self):  # 배포 시 병합, 추가 지연 없음
        return self.W0 + self.scale * (self.B @ self.A)

parity.pseudocode:
def parity(blocks):
    p = 0
    for b in blocks:
        p ^= b  # P = D1 ⊕ D2 ⊕ ... ⊕ Dn
    return p

def rebuild(survivors, p):  # 블록 1개 손실 시
    x = p
    for b in survivors:
        x ^= b
    return x  # 손실 블록 복원값

def small_write(old_d, new_d, old_p):
    # 구 D·구 P 읽기 2회 + 새 D·새 P 쓰기 2회 = 쓰기 페널티
    return old_p ^ old_d ^ new_d  # 새 패리티

