quadtree.pseudocode:
class QuadTree:  # PR 쿼드트리
    def __init__(self, box, cap=4):
        self.box, self.cap = box, cap  # box=(x0,y0,x1,y1)
        self.points, self.kids = [], None

    def insert(self, p):
        if not contains(self.box, p):
            return False
        if self.kids is None:
            if len(self.points) < self.cap:
                self.points.append(p)
                return True
            self.split()  # 용량 초과 → 4분할
        return any(k.insert(p) for k in self.kids)

    def split(self):
        x0, y0, x1, y1 = self.box
        mx, my = (x0 + x1) / 2, (y0 + y1) / 2
        self.kids = [QuadTree(b, self.cap) for b in (
            (x0, my, mx, y1), (mx, my, x1, y1),  # NW, NE
            (x0, y0, mx, my), (mx, y0, x1, my))]  # SW, SE
        for q in self.points:  # 기존 점 재배치
            any(k.insert(q) for k in self.kids)
        self.points = []

queue.pseudocode:
class CircularQueue:
    def __init__(self, n):
        self.q = [None] * n
        self.n = n
        # 한 칸을 비워 포화·공백을 구분
        self.front = self.rear = 0

    def enqueue(self, x):
        nxt = (self.rear + 1) % self.n
        if nxt == self.front:
            raise OverflowError  # 포화
        self.rear = nxt
        self.q[self.rear] = x

    def dequeue(self):
        if self.front == self.rear:
            raise IndexError  # 공백
        self.front = (self.front + 1) % self.n
        return self.q[self.front]

raid.pseudocode:
def parity(blocks):
    p = 0
    for b in blocks:
        p ^= b  # 같은 스트라이프 데이터 XOR
    return p

def rebuild(surviving, p):
    # 장애 블록 = 남은 데이터 블록 XOR 패리티
    return parity(surviving + [p])

def update_parity(old_d, new_d, old_p):
    # RAID 5 쓰기: 읽기-수정-쓰기(쓰기 페널티)
    return old_p ^ old_d ^ new_d

rainbow-table.pseudocode:
def build_chain(start, t, reduce, H):
    # 시작값에서 H와 R(위치별)을 t회 교대 적용
    x = start
    for i in range(t):
        h = H(x)
        x = reduce(h, i)  # 체인 위치마다 다른 환원
    return start, x  # 시작값·끝값만 저장

def lookup(target_hash, table, t, reduce, H):
    # 끝 열부터 거슬러 올라가며 체인 탐색
    for j in range(t - 1, -1, -1):
        x = reduce(target_hash, j)
        for i in range(j + 1, t):
            x = reduce(H(x), i)
        if x in table:  # 끝값 매칭 → 후보 체인
            cand = regenerate(table[x], t, reduce, H)
            if H(cand) == target_hash:
                return cand  # 평문 복원
    return None  # 솔트 적용 시 사실상 실패

rasterization.pseudocode:
def edge(a, b, p):  # p가 변 ab의 어느 쪽인지(부호)
    return ((b.x - a.x) * (p.y - a.y)
            - (b.y - a.y) * (p.x - a.x))

def raster_triangle(v0, v1, v2, zbuf, frame, color):
    area = edge(v0, v1, v2)
    if area == 0:
        return  # 퇴화 삼각형
    xs, ys = [v0.x, v1.x, v2.x], [v0.y, v1.y, v2.y]
    for y in range(int(min(ys)), int(max(ys)) + 1):
        for x in range(int(min(xs)), int(max(xs)) + 1):
            p = Point(x + 0.5, y + 0.5)  # 픽셀 중심
            w0 = edge(v1, v2, p) / area  # 무게중심 좌표
            w1 = edge(v2, v0, p) / area
            w2 = edge(v0, v1, p) / area
            if w0 < 0 or w1 < 0 or w2 < 0:
                continue  # 삼각형 밖
            z = w0 * v0.z + w1 * v1.z + w2 * v2.z  # 보간
            if z < zbuf[y][x]:  # 깊이 테스트
                zbuf[y][x] = z
                frame[y][x] = color

ray-tracing.pseudocode:
def trace(ray, depth):
    hit = nearest_hit(ray)  # 최근접 교차 = 은면제거
    if hit is None:
        return BACKGROUND
    m = hit.material
    color = AMBIENT * m.color
    for light in lights:
        shadow = Ray(hit.point, light.pos - hit.point)
        if not blocked(shadow, light):  # 그림자 판정
            color += shade(hit, light)  # 확산·정반사
    if depth < MAX_DEPTH:
        if m.reflect > 0:
            r = reflect_ray(ray, hit)
            color += m.reflect * trace(r, depth + 1)
        if m.refract > 0:
            t = refract_ray(ray, hit, m.ior)
            color += m.refract * trace(t, depth + 1)
    return color

def render(w, h):
    for y in range(h):
        for x in range(w):
            image[y][x] = trace(primary_ray(x, y), 0)

