robo-advisor.pseudocode:
def rebalance(holdings, target, prices, band=0.05):
    # target: 자산별 목표 비중 {자산: 비율}
    total = sum(holdings[a] * prices[a] for a in holdings)
    orders = {}
    for a in target:
        cur_val = holdings[a] * prices[a]
        cur_w = cur_val / total  # 현재 비중
        if abs(cur_w - target[a]) > band:  # 허용밴드 초과
            target_val = total * target[a]
            diff = target_val - cur_val
            orders[a] = diff / prices[a]  # 매수(+)·매도(-)
    return orders

rolling-deployment.pseudocode:
def rolling_deploy(servers, new_ver, batch_size, lb):
    done = []
    for i in range(0, len(servers), batch_size):
        batch = servers[i:i + batch_size]
        for s in batch:
            lb.drain(s)  # 신규 트래픽 차단, 처리 중 요청 완료
            s.install(new_ver)
            s.restart()
        if not all(s.health_check() for s in batch):
            # 실패: 진행 중단, 교체한 서버 모두 원복
            for s in done + batch:
                s.install(s.prev_ver)
                s.restart()
                lb.enable(s)
            return 'rollback'
        for s in batch:
            lb.enable(s)  # 트래픽 복귀 (신구 버전 공존)
        done += batch
    return 'success'

root-finding.pseudocode:
def bisection(f, a, b, tol=1e-10):
    assert f(a) * f(b) < 0  # 부호 변화 → 구간 안에 근 존재
    while b - a > tol:
        m = (a + b) / 2
        if f(a) * f(m) <= 0:  # 근이 왼쪽 반에 있음
            b = m
        else:
            a = m
    return (a + b) / 2

def newton(f, df, x, tol=1e-12, max_iter=50):
    for _ in range(max_iter):
        step = f(x) / df(x)  # 접선의 x절편으로 이동
        x -= step
        if abs(step) < tol:
            return x
    raise ValueError('수렴 실패: 초기값 재선정')

roulette-wheel-selection.pseudocode:
def roulette_select(pop, fitness):
    total = sum(fitness)  # 적합도는 0 이상이어야 함
    r = uniform(0, total)  # 룰렛 회전
    acc = 0.0
    for ind, f in zip(pop, fitness):
        acc += f  # 적합도 비례 구간 누적
        if r <= acc:
            return ind
    return pop[-1]  # 부동소수 오차 대비

parents = [roulette_select(pop, fit) for _ in pop]

round-function.pseudocode:
def feistel_encrypt(block, round_keys, F):
    # block을 좌우 절반으로 분할
    L, R = split_half(block)
    for k in round_keys:
        L, R = R, L ^ F(R, k)  # 라운드: 오른쪽에 F 적용
    return R + L  # 마지막 라운드 후 교환하지 않음

def feistel_decrypt(block, round_keys, F):
    # 라운드 키를 역순으로 적용하면 복호
    R, L = split_half(block)
    for k in reversed(round_keys):
        R, L = L, R ^ F(L, k)
    return L + R

round-robin-scheduling.pseudocode:
def round_robin(bursts, q):
    # bursts: {pid: CPU 실행시간}, 모두 0시점 도착 가정
    queue = list(bursts)  # FIFO 준비 큐
    remain = dict(bursts)
    t, finish = 0, {}
    while queue:
        p = queue.pop(0)
        run = min(q, remain[p])  # 최대 퀀텀만큼 실행
        t += run
        remain[p] -= run
        if remain[p] == 0:
            finish[p] = t  # 완료 시각
        else:
            queue.append(p)  # 선점 후 큐 맨 뒤로
    return finish

routing-information-protocol.pseudocode:
INF = 16  # 홉 수 16 = 도달 불가

def on_update(table, neighbor, adv):
    # table[dst] = (홉 수, 다음 홉), adv = 이웃 광고 {dst: 홉 수}
    for dst, m in adv.items():
        new = min(m + 1, INF)  # 이웃까지 1홉 추가
        cur = table.get(dst)
        if cur is None:
            if new < INF:
                table[dst] = (new, neighbor)  # 새 경로
        elif cur[1] == neighbor:
            table[dst] = (new, neighbor)  # 현 다음 홉 정보는 항상 반영
        elif new < cur[0]:
            table[dst] = (new, neighbor)  # 더 짧은 경로로 교체

def advertise(table, to_neighbor):  # 30초마다 전체 테이블
    # 포이즌 리버스: 그 이웃에게서 배운 경로는 16으로 광고
    return {d: (INF if nh == to_neighbor else m)
            for d, (m, nh) in table.items()}

routing-table.pseudocode:
class TrieNode:
    def __init__(self):
        self.child = {}  # '0' / '1' → 자식 노드
        self.next_hop = None

def insert(root, prefix_bits, next_hop):  # '1010…' 비트열
    node = root
    for b in prefix_bits:
        node = node.child.setdefault(b, TrieNode())
    node.next_hop = next_hop

def lookup(root, addr_bits):  # 최장 접두사 일치(LPM)
    node, best = root, root.next_hop  # /0 기본 경로
    for b in addr_bits:
        node = node.child.get(b)
        if node is None:
            break
        if node.next_hop is not None:
            best = node.next_hop  # 더 긴 일치로 갱신
    return best

rpki.pseudocode:
def covers(vp, vlen, p, plen):  # VRP 대역이 광고 대역 포함?
    if plen < vlen:
        return False
    shift = 32 - vlen
    return (vp >> shift) == (p >> shift)

def rov(prefix, plen, origin_as, vrps):
    # vrps: ROA 검증 결과 (프리픽스, 길이, 최대 길이, AS)
    covered = False
    for vp, vlen, maxlen, asn in vrps:
        if covers(vp, vlen, prefix, plen):
            covered = True  # 해당 대역에 ROA 존재
            if origin_as == asn and plen <= maxlen:
                return 'Valid'
    return 'Invalid' if covered else 'NotFound'

run-length-encoding.pseudocode:
def rle_encode(data):
    out, i = [], 0
    while i < len(data):
        j = i
        while j < len(data) and data[j] == data[i]:
            j += 1  # 같은 값이 이어지는 끝 찾기
        out.append((data[i], j - i))  # (값, 반복 횟수)
        i = j
    return out

def rle_decode(pairs):
    return ''.join(v * n for v, n in pairs)

safe-state.pseudocode:
def is_safe(avail, alloc, need):  # 은행가 안전성 검사
    work = avail[:]  # 현재 사용 가능 자원
    n, m = len(alloc), len(avail)
    finish = [False] * n
    order = []
    while len(order) < n:
        found = False
        for i in range(n):
            if finish[i]:
                continue
            if all(need[i][j] <= work[j] for j in range(m)):
                for j in range(m):
                    work[j] += alloc[i][j]  # 완료 후 반납
                finish[i] = True
                order.append(i)
                found = True
        if not found:
            return False, order  # 불안전 상태
    return True, order  # 안전 순서열

sat-solver.pseudocode:
def val(lit, a):  # 리터럴 값: True/False/None(미할당)
    v = a.get(abs(lit))
    return None if v is None else v == (lit > 0)

def dpll(cnf, a):  # cnf: 절 리스트, 리터럴은 ±변수번호
    changed = True
    while changed:  # 단위 전파(BCP)
        changed = False
        for c in cnf:
            vals = [val(l, a) for l in c]
            if True in vals:
                continue  # 이미 충족된 절
            free = [l for l, v in zip(c, vals) if v is None]
            if not free:
                return None  # 충돌: 모든 리터럴 거짓
            if len(free) == 1:  # 단위 절 → 강제 할당
                a[abs(free[0])] = free[0] > 0
                changed = True
    free = {abs(l) for c in cnf for l in c} - set(a)
    if not free:
        return a  # SAT: 충족 할당(= 반례)
    v = min(free)  # 결정 변수 선택
    for b in (True, False):
        r = dpll(cnf, {**a, v: b})
        if r is not None:
            return r
    return None  # UNSAT (CDCL은 학습 절 + 백점프)

scene-graph.pseudocode:
def render(node, parent_world, camera):
    # 부모 변환 누적: 월드 = 부모 월드 × 로컬
    world = parent_world @ node.local
    # bounds는 자식까지 포함한 계층적 경계 볼륨
    box = node.bounds.transform(world)
    if not camera.frustum.intersects(box):
        return  # 절두체 컬링: 하위 트리 전체 생략
    if node.mesh:
        lod = node.select_lod(camera.distance(box))
        draw(lod, node.material, world)
    for child in node.children:
        render(child, world, camera)

schedulability-analysis.pseudocode:
def response_time(tasks, i, b=0):
    # tasks: 우선순위 내림차순 [(C, T)], 마감 = 주기
    c, t = tasks[i]
    r = c + b  # b: 블로킹 시간
    while True:
        # 상위 태스크 간섭: ceil(r/Tj) × Cj
        interf = sum(-(-r // tj) * cj
                     for cj, tj in tasks[:i])
        r_new = c + b + interf
        if r_new > t:
            return None  # 마감 초과
        if r_new == r:
            return r  # 수렴: 최악 응답시간
        r = r_new

def schedulable(tasks):
    return all(response_time(tasks, i) is not None
               for i in range(len(tasks)))

search-engine.pseudocode:
def build_index(docs):  # docs: {문서ID: 단어 목록}
    index = {}  # 역색인: 단어 -> {문서ID: 빈도}
    for d, words in docs.items():
        for w in words:
            index.setdefault(w, {})
            index[w][d] = index[w].get(d, 0) + 1
    return index

def search(query, index, n_docs):  # TF-IDF 점수 순위화
    scores = {}
    for w in query:
        postings = index.get(w, {})
        if not postings:
            continue
        idf = log(n_docs / len(postings))  # 희귀 단어일수록 큼
        for d, tf in postings.items():
            scores[d] = scores.get(d, 0) + tf * idf
    return sorted(scores, key=scores.get, reverse=True)

secant-method.pseudocode:
def secant(f, x0, x1, eps=1e-10, max_iter=50):
    for _ in range(max_iter):
        f0, f1 = f(x0), f(x1)
        if f1 == f0:
            raise ZeroDivisionError('수평 할선')
        x2 = x1 - f1 * (x1 - x0) / (f1 - f0)  # 할선의 x절편
        if abs(x2 - x1) < eps:
            return x2
        x0, x1 = x1, x2  # 최근 두 점으로 갱신
    return x1  # 최대 반복 도달

print(secant(lambda x: x * x - 2, 1.0, 2.0))  # √2 ≈ 1.41421

second-chance-algorithm.pseudocode:
def access(queue, ref, page, capacity):
    if page in queue:
        ref[page] = 1  # 적중: 참조 비트만 설정
        return 'hit'
    if len(queue) == capacity:
        while True:
            victim = queue.pop(0)  # FIFO 맨 앞
            if ref[victim] == 1:
                ref[victim] = 0  # 비트 해제 후 한 번 더 기회
                queue.append(victim)
            else:
                del ref[victim]  # 비트 0 → 교체
                break
    queue.append(page)
    ref[page] = 1  # 적재 시 참조됨
    return 'fault'

secret-sharing.pseudocode:
def split(secret, t, n, prime):
    # t-1차 다항식: f(0)=secret, 나머지 계수는 난수
    coef = [secret] + [random_int(1, prime - 1)
                       for _ in range(t - 1)]
    def f(x):
        return sum(c * pow(x, k, prime)
                   for k, c in enumerate(coef)) % prime
    return [(i, f(i)) for i in range(1, n + 1)]

def recover(shares, prime):
    # t개 이상 조각으로 라그랑주 보간 → f(0)
    secret = 0
    for i, (xi, yi) in enumerate(shares):
        num, den = 1, 1
        for j, (xj, _) in enumerate(shares):
            if i != j:
                num = num * (-xj) % prime
                den = den * (xi - xj) % prime
        secret += yi * num * pow(den, -1, prime)
    return secret % prime

selection-pressure.pseudocode:
def tournament_select(pop, fitness, k):
    # k가 클수록 선택압 증가 (k=1이면 무작위 선택)
    contestants = [random_choice(pop) for _ in range(k)]
    return max(contestants, key=fitness)

def roulette_select(pop, fitness):  # 적합도 비례 선택
    total = sum(fitness(x) for x in pop)
    r = random_uniform(0, total)
    acc = 0
    for x in pop:
        acc += fitness(x)
        if acc >= r:
            return x
    return pop[-1]

selection-sort.pseudocode:
def selection_sort(a):
    n = len(a)
    for i in range(n - 1):
        m = i  # 미정렬 구간의 최소값 위치
        for j in range(i + 1, n):
            if a[j] < a[m]:
                m = j
        if m != i:
            a[i], a[m] = a[m], a[i]  # 교환 최대 n-1회
    return a  # 비교 항상 n(n-1)/2회 → O(n²)

self-balancing-binary-search-tree.pseudocode:
def rotate_right(y):
    x = y.left
    y.left = x.right
    x.right = y
    update_height(y)
    update_height(x)
    return x  # 새 서브트리 루트 (rotate_left는 대칭)

def rebalance(n):  # AVL 기준, 삽입·삭제 경로마다 호출
    update_height(n)
    bf = height(n.left) - height(n.right)
    if bf > 1:  # 왼쪽 과중
        if height(n.left.left) < height(n.left.right):
            n.left = rotate_left(n.left)  # LR → LL
        return rotate_right(n)
    if bf < -1:  # 오른쪽 과중
        if height(n.right.right) < height(n.right.left):
            n.right = rotate_right(n.right)  # RL → RR
        return rotate_left(n)
    return n

self-healing.pseudocode:
def reconcile(desired, list_pods, create_pod, delete_pod):
    while True:  # 컨트롤러 조정 루프
        pods = [p for p in list_pods() if p.healthy]
        for p in list_pods():
            if not p.healthy:
                delete_pod(p)  # 실패 Pod 제거
        for _ in range(max(desired - len(pods), 0)):
            create_pod()  # 부족분 생성 (가용 노드에 배치)
        for p in pods[desired:]:
            delete_pod(p)  # 초과분 삭제
        wait_for_change()  # 상태 변화 감시 후 반복

semi-supervised-learning.pseudocode:
def self_training(labeled, unlabeled, train, predict,
                  th=0.9, rounds=5):  # 자기학습
    model = train(labeled)
    for _ in range(rounds):
        rest = []
        for x in unlabeled:
            label, prob = predict(model, x)
            if prob >= th:  # 고신뢰 예측만 의사 라벨로 채택
                labeled.append((x, label))
            else:
                rest.append(x)
        if len(rest) == len(unlabeled):
            break  # 추가된 샘플 없음 → 종료
        unlabeled = rest
        model = train(labeled)  # 확장된 데이터로 재학습
    return model

separate-chaining.pseudocode:
class ChainedHash:
    def __init__(self, m):
        self.m = m
        self.table = [[] for _ in range(m)]  # 버킷별 체인

    def insert(self, key, val):
        chain = self.table[key % self.m]
        for i, (k, _) in enumerate(chain):
            if k == key:
                chain[i] = (key, val)  # 같은 키면 갱신
                return
        chain.append((key, val))  # 충돌해도 체인에 연결

    def search(self, key):
        for k, v in self.table[key % self.m]:  # 체인 순회
            if k == key:
                return v
        return None

    def delete(self, key):
        b = key % self.m  # 포인터 조정만으로 삭제
        self.table[b] = [e for e in self.table[b]
                         if e[0] != key]

sequential-pattern-mining.pseudocode:
def prefixspan(db, min_sup, prefix=None, out=None):
    # db: 시퀀스 목록 (각 시퀀스는 시간순 항목 리스트)
    prefix = prefix or []
    out = [] if out is None else out
    counts = {}
    for seq in db:
        for item in set(seq):  # 시퀀스당 1회만 계수
            counts[item] = counts.get(item, 0) + 1
    for item, sup in counts.items():
        if sup < min_sup:
            continue
        pattern = prefix + [item]
        out.append((pattern, sup))
        projected = []  # item 첫 등장 이후의 접미 시퀀스
        for seq in db:
            if item in seq:
                suffix = seq[seq.index(item) + 1:]
                if suffix:
                    projected.append(suffix)
        prefixspan(projected, min_sup, pattern, out)
    return out

serializability.pseudocode:
def conflict_serializable(schedule):  # [(txn, op, item)]
    edges = set()
    for i, (ti, opi, xi) in enumerate(schedule):
        for tj, opj, xj in schedule[i + 1:]:
            # 같은 항목·다른 트랜잭션·쓰기 포함 → 충돌
            if xi == xj and ti != tj and 'W' in (opi, opj):
                edges.add((ti, tj))  # ti → tj 선행
    txns = {t for t, _, _ in schedule}
    indeg = {t: 0 for t in txns}
    for _, b in edges:
        indeg[b] += 1
    ready = [t for t in txns if indeg[t] == 0]
    order = []
    while ready:  # 위상 정렬로 사이클 검사
        u = ready.pop()
        order.append(u)
        for a, b in edges:
            if a == u:
                indeg[b] -= 1
                if indeg[b] == 0:
                    ready.append(b)
    if len(order) < len(txns):
        return None  # 사이클 → 충돌 직렬 불가
    return order  # 동등한 직렬 실행 순서

shell.pseudocode:
def shell():
    while True:
        args = input('$ ').split()  # 프롬프트·파싱
        if not args:
            continue
        if args[0] == 'cd':  # 내장 명령: 셸이 직접 처리
            chdir(args[1])
            continue
        pid = fork()  # 자식 프로세스 복제
        if pid == 0:
            exec(args[0], args)  # 자식: 프로그램으로 교체
            exit(127)  # exec 실패 시
        else:
            waitpid(pid)  # 부모: 종료 대기 후 다음 명령

shor-algorithm.pseudocode:
def shor(N):  # N: 홀수 합성수(소수 거듭제곱 아님)
    while True:
        a = random_int(2, N - 1)
        g = gcd(a, N)
        if g > 1:
            return g, N // g  # 우연히 인수 발견
        r = quantum_period(a, N)  # QFT: a^x mod N 주기
        if r % 2 == 1:
            continue  # 홀수 주기 → 다른 a로 재시도
        y = pow(a, r // 2, N)
        if y == N - 1:
            continue  # a^(r/2) ≡ -1 → 재시도
        p = gcd(y - 1, N)  # (y-1)(y+1) ≡ 0 mod N
        return p, N // p

shortest-path.pseudocode:
def dijkstra(graph, src):  # 음수 가중치 없음 전제
    dist = {v: INF for v in graph}
    prev = {v: None for v in graph}
    dist[src] = 0
    pq = MinHeap([(0, src)])  # (거리, 정점)
    while pq:
        d, u = pq.pop_min()
        if d > dist[u]:
            continue  # 이미 더 짧게 확정된 정점
        for v, w in graph[u]:  # 간선 완화
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                prev[v] = u  # 최단경로 트리 기록
                pq.push((dist[v], v))
    return dist, prev

shortest-remaining-time-first.pseudocode:
def srtf(procs):  # procs: {이름: (도착, 버스트)}
    remain = {p: b for p, (a, b) in procs.items()}
    time, finish = 0, {}
    while remain:
        ready = [p for p in remain if procs[p][0] <= time]
        if not ready:
            time += 1
            continue
        # 매 시점 잔여시간 최소 선택 → 도착 시 선점 반영
        p = min(ready, key=lambda q: remain[q])
        remain[p] -= 1  # 1단위 실행
        time += 1
        if remain[p] == 0:
            del remain[p]
            finish[p] = time
    waits = [finish[p] - a - b  # 대기 = 종료 − 도착 − 버스트
             for p, (a, b) in procs.items()]
    return finish, sum(waits) / len(waits)

signature-file.pseudocode:
F, M = 16, 3  # 시그니처 비트 수, 단어당 1인 비트 수
def word_sig(word):
    sig = 0
    for i in range(M):
        sig |= 1 << (hash((word, i)) % F)
    return sig

def block_sig(words):
    sig = 0
    for w in words:
        sig |= word_sig(w)  # 중첩 부호화(OR)
    return sig

def search(blocks, sigs, query_words):
    q = block_sig(query_words)
    result = []
    for blk, s in zip(blocks, sigs):
        if s & q == q:  # 비트 비교로 후보 선별
            if all(w in blk for w in query_words):
                result.append(blk)  # False Drop 제거
    return result

