sliding-window-protocol.pseudocode:
def gbn_sender(frames, W):  # Go-Back-N 송신 측
    base = next_seq = 0  # base: 가장 오래된 미확인
    while base < len(frames):
        # 윈도 안이면 ACK 없이 연속 송신
        while next_seq < min(base + W, len(frames)):
            send(next_seq, frames[next_seq])
            if next_seq == base:
                start_timer()
            next_seq += 1
        ev = wait_event()  # 누적 ACK 또는 타임아웃
        if ev.kind == 'ack' and ev.num >= base:
            base = ev.num + 1  # 윈도 슬라이드
            if base < next_seq:
                start_timer()
        elif ev.kind == 'timeout':
            next_seq = base  # base부터 다시 송신

smart-proxy.pseudocode:
class SmartProxy:  # Subject와 같은 인터페이스
    def __init__(self, factory):
        self.factory = factory
        self.real = None
        self.ref_count = 0
        self.lock = Lock()

    def acquire(self):
        self.ref_count += 1  # 참조 카운트 증가

    def release(self):
        self.ref_count -= 1
        if self.ref_count == 0:
            self.real = None  # 마지막 참조 해제 시 소멸

    def request(self, *args):
        with self.lock:  # 동시 접근 제어(락)
            if self.real is None:
                self.real = self.factory()  # 최초 접근 시 생성
            log('request', args)  # 접근 로깅 후 위임
            return self.real.request(*args)

sort-merge-join.pseudocode:
def sort_merge_join(A, B, key):
    A, B = sorted(A, key=key), sorted(B, key=key)  # 정렬
    i = j = 0
    out = []
    while i < len(A) and j < len(B):  # 병합 단계
        ka, kb = key(A[i]), key(B[j])
        if ka < kb:
            i += 1
        elif ka > kb:
            j += 1
        else:  # 같은 키 그룹끼리 모두 결합
            j_end = j
            while j_end < len(B) and key(B[j_end]) == ka:
                j_end += 1
            while i < len(A) and key(A[i]) == ka:
                for b in B[j:j_end]:
                    out.append((A[i], b))
                i += 1
            j = j_end
    return out

space-complexity.pseudocode:
def sum_rec(a, n):  # 스택 깊이 n → 보조 공간 O(n)
    if n == 0:
        return 0
    return a[n - 1] + sum_rec(a, n - 1)

def sum_iter(a):  # 변수만 사용 → 보조 공간 O(1)
    total = 0
    for x in a:
        total += x
    return total

def fib(n):  # DP 테이블 O(n) 대신 직전 두 값만 → O(1)
    prev, cur = 0, 1
    for _ in range(n):
        prev, cur = cur, prev + cur
    return prev

spanning-tree.pseudocode:
def bfs_spanning_tree(graph, start):
    visited = {start}
    queue = [start]
    tree = []  # 신장 트리 간선
    while queue:
        u = queue.pop(0)
        for v in graph[u]:
            if v not in visited:  # 처음 만나는 정점만 → 사이클 없음
                visited.add(v)
                tree.append((u, v))
                queue.append(v)
    return tree  # 연결 그래프면 간선 수 = V - 1

spn-structure.pseudocode:
def substitute(s, sbox):  # 4비트 S-박스 4개 병렬
    out = 0
    for i in range(4):
        out |= sbox[(s >> 4 * i) & 0xF] << 4 * i
    return out

def permute(s, perm):  # 비트 전치(P-박스)
    out = 0
    for i in range(16):
        if (s >> i) & 1:
            out |= 1 << perm[i]
    return out

def spn_encrypt(x, keys, sbox, perm):
    nr = len(keys) - 1  # 라운드 수, 키는 nr+1개
    for r in range(nr - 1):
        x = substitute(x ^ keys[r], sbox)  # 키 혼합 → 혼돈
        x = permute(x, perm)  # 확산
    x = substitute(x ^ keys[nr - 1], sbox)  # 마지막: 전치 생략
    return x ^ keys[nr]  # 최종 키 화이트닝

stack.pseudocode:
class ArrayStack:
    def __init__(self, capacity):
        self.data = [None] * capacity
        self.top = -1  # 비어 있음

    def push(self, x):  # O(1)
        if self.top == len(self.data) - 1:
            raise OverflowError('스택 오버플로')
        self.top += 1
        self.data[self.top] = x

    def pop(self):  # O(1), 후입선출
        if self.top == -1:
            raise IndexError('스택 언더플로')
        x = self.data[self.top]
        self.top -= 1
        return x

    def peek(self):
        if self.top == -1:
            raise IndexError('스택 언더플로')
        return self.data[self.top]

stack-based-virtual-machine.pseudocode:
def run(code):
    stack = []  # 피연산자 스택 (레지스터 없음)
    for op, arg in code:
        if op == 'PUSH':
            stack.append(arg)
        else:  # 이항 연산: pop 2개 → 결과 push
            b = stack.pop()  # 오른쪽 피연산자 먼저
            a = stack.pop()
            if op == 'ADD':
                stack.append(a + b)
            elif op == 'SUB':
                stack.append(a - b)
            elif op == 'MUL':
                stack.append(a * b)
    return stack.pop()

# (2+3)*4 → PUSH 2, PUSH 3, ADD, PUSH 4, MUL
# 스택: [2] → [2,3] → [5] → [5,4] → [20]

stacking.pseudocode:
def stacking_fit(X, y, base_models, meta_model, k=5):
    n = len(X)
    oof = [[0.0] * len(base_models) for _ in range(n)]
    for tr_idx, va_idx in kfold(n, k):
        for j, m in enumerate(base_models):
            m.fit(X[tr_idx], y[tr_idx])
            preds = m.predict(X[va_idx])
            for i, p in zip(va_idx, preds):
                oof[i][j] = p  # 학습에 안 쓴 폴드만 예측
    meta_model.fit(oof, y)  # 기반 예측값 → 메타 특성
    for m in base_models:
        m.fit(X, y)  # 추론용: 전체 데이터로 재학습
    return base_models, meta_model

def stacking_predict(x, base_models, meta_model):
    z = [m.predict([x])[0] for m in base_models]
    return meta_model.predict([z])[0]

