stratified-k-fold.pseudocode:
def stratified_kfold(labels, k):
    folds = [[] for _ in range(k)]
    by_class = {}
    for i, c in enumerate(labels):
        by_class.setdefault(c, []).append(i)
    for idx in by_class.values():  # 클래스별로 따로 분배
        shuffle(idx)
        for j, i in enumerate(idx):
            folds[j % k].append(i)  # 순환 배치 → 비율 유지
    for f in range(k):
        test = folds[f]
        train = [i for g in range(k) if g != f
                 for i in folds[g]]
        yield train, test

stream-cipher.pseudocode:
def stream_encrypt(key, nonce, data):
    ks = keystream(key, nonce, len(data))  # 키스트림 생성
    return bytes(d ^ k for d, k in zip(data, ks))

def stream_decrypt(key, nonce, data):
    return stream_encrypt(key, nonce, data)  # XOR은 자기 역원

# 같은 (key, nonce) 재사용 시
# C1 XOR C2 = P1 XOR P2 → 평문 정보 노출
# 따라서 메시지마다 nonce를 새로 사용

streaming-api-for-xml.pseudocode:
def sum_prices(reader):  # reader: XMLStreamReader 커서
    total, in_price = 0.0, False
    while reader.has_next():  # 응용이 다음 이벤트를 당김(Pull)
        event = reader.next()
        if event == START_ELEMENT:
            in_price = reader.local_name() == 'price'
        elif event == CHARACTERS and in_price:
            total += float(reader.text())  # 필요한 값만 처리
        elif event == END_ELEMENT:
            in_price = False
    reader.close()
    return total  # 메모리 사용량은 문서 크기와 무관

subset-construction.pseudocode:
def eps_closure(nfa, states):
    stack, closure = list(states), set(states)
    while stack:
        for r in nfa.eps.get(stack.pop(), []):  # ε 전이
            if r not in closure:
                closure.add(r)
                stack.append(r)
    return frozenset(closure)

def move(nfa, T, a):
    return {r for q in T for r in nfa.delta.get((q, a), ())}

def subset_construction(nfa):
    start = eps_closure(nfa, {nfa.start})
    dstates, work, trans = {start}, [start], {}
    while work:  # 미표시 DFA 상태 처리
        T = work.pop()
        for a in nfa.alphabet:
            U = eps_closure(nfa, move(nfa, T, a))
            trans[(T, a)] = U  # 빈 집합 = 죽은 상태
            if U not in dstates:
                dstates.add(U)
                work.append(U)
    accept = {S for S in dstates if S & nfa.accepts}
    return dstates, start, trans, accept

substitution-cipher.pseudocode:
def caesar(text, k):  # 단일 치환: 고정 이동
    out = []
    for ch in text:
        if ch.isupper():
            out.append(chr((ord(ch) - 65 + k) % 26 + 65))
        else:
            out.append(ch)  # 대문자 외는 그대로
    return ''.join(out)

def vigenere(text, key):  # 다중 치환: 위치별 이동량
    out = []
    for i, ch in enumerate(text):
        k = ord(key[i % len(key)]) - 65
        out.append(chr((ord(ch) - 65 + k) % 26 + 65))
    return ''.join(out)

# caesar('HELLO', 3) → 'KHOOR'

subword-tokenization.pseudocode:
def learn_bpe(freq, num_merges):  # freq: 단어 → 빈도
    # 문자 단위 분할 + 단어 끝 기호
    voc = {tuple(w) + ('</w>',): f for w, f in freq.items()}
    merges = []
    for _ in range(num_merges):
        pairs = {}
        for sym, f in voc.items():  # 인접 쌍 빈도 집계
            for a, b in zip(sym, sym[1:]):
                pairs[(a, b)] = pairs.get((a, b), 0) + f
        if not pairs:
            break  # 더 병합할 쌍 없음
        best = max(pairs, key=pairs.get)  # 최빈 쌍 병합
        merges.append(best)
        voc = {merge(s, best): f for s, f in voc.items()}
    return merges  # 병합 규칙 = 서브워드 어휘

def merge(sym, pair):
    out, i = [], 0
    while i < len(sym):
        if tuple(sym[i:i + 2]) == pair:  # 쌍을 한 기호로
            out.append(sym[i] + sym[i + 1])
            i += 2
        else:
            out.append(sym[i])
            i += 1
    return tuple(out)

successive-interference-cancellation.pseudocode:
def sic_detect(y, users):
    decoded = {}
    # 수신 전력이 강한 사용자부터 순차 복호
    order = sorted(users, key=lambda u: -u.rx_power)
    for u in order:
        bits = decode(y, u)  # 남은 약한 신호는 잡음 취급
        decoded[u.id] = bits
        regen = u.channel * modulate(bits) * u.amplitude
        y = y - regen  # 재생 신호를 빼서 간섭 제거
    return decoded  # 앞 단계 오류는 뒤로 전파

super-key.pseudocode:
def closure(attrs, fds):  # fds: [(좌변 집합, 우변 집합)]
    result = set(attrs)
    changed = True
    while changed:
        changed = False
        for lhs, rhs in fds:
            # 좌변이 모두 포함되면 우변을 추가
            if lhs <= result and not rhs <= result:
                result |= rhs
                changed = True
    return result

def is_super_key(attrs, all_attrs, fds):
    return closure(attrs, fds) >= set(all_attrs)

surrogate-gradient.pseudocode:
class SpikeFn:  # 순전파는 계단, 역전파는 대리 미분
    @staticmethod
    def forward(u, theta=1.0):
        return 1.0 if u >= theta else 0.0  # 이진 스파이크

    @staticmethod
    def backward(u, grad_out, theta=1.0, k=10.0):
        # 계단 함수의 미분(델타) 대신
        # 고속 시그모이드 미분 1/(1+k|u-θ|)^2 사용
        surrogate = 1.0 / (1.0 + k * abs(u - theta)) ** 2
        return grad_out * surrogate

surrogate-pair.pseudocode:
def to_utf16(cp):
    if cp < 0x10000:
        return [cp]  # BMP: 단일 코드 유닛
    v = cp - 0x10000  # 20비트 값
    hi = 0xD800 + (v >> 10)  # 상위 10비트
    lo = 0xDC00 + (v & 0x3FF)  # 하위 10비트
    return [hi, lo]

def from_utf16(hi, lo):
    assert 0xD800 <= hi <= 0xDBFF and 0xDC00 <= lo <= 0xDFFF
    return 0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)

