symbolic-model-checking.pseudocode:
# 상태 집합 R, 전이 T는 BDD로 표현 (개별 열거 없음)
def image(R, T):  # R에서 한 단계 후 상태 집합
    return exists_current(R & T).rename_next_to_current()

def check_invariant(init, T, bad):
    R = init
    while True:
        if not (R & bad).is_empty():
            return 'violated'  # 반례 존재
        nxt = R | image(R, T)
        if nxt == R:  # 고정점: 더 이상 새 상태 없음
            return 'holds'
        R = nxt

t-tree.pseudocode:
def t_tree_search(node, k):
    while node is not None:
        if k < node.keys[0]:  # 노드 min보다 작음
            node = node.left
        elif k > node.keys[-1]:  # 노드 max보다 큼
            node = node.right
        else:  # 바운딩 노드: 노드 안에서 이진 탐색
            return binary_search(node.keys, k)
    return None  # 키 없음

tabu-search.pseudocode:
def tabu_search(s0, f, max_iter, tenure):
    best = cur = s0
    tabu = []  # 최근 이동 금지 목록 (FIFO)
    for _ in range(max_iter):
        cands = []
        for move in moves(cur):
            s = apply(cur, move)
            # 타부여도 최고해를 갱신하면 허용 (열망 기준)
            if move not in tabu or f(s) < f(best):
                cands.append((f(s), move, s))
        if not cands:
            break
        _, move, cur = min(cands, key=lambda c: c[0])
        tabu.append(inverse(move))  # 되돌아가기 금지
        if len(tabu) > tenure:
            tabu.pop(0)
        if f(cur) < f(best):
            best = cur
    return best

tail-recursion.pseudocode:
def fact(n):  # 일반 재귀: 호출 후 곱셈 남음
    if n <= 1:
        return 1
    return n * fact(n - 1)

def fact_tail(n, acc=1):  # 꼬리 재귀: 호출이 마지막
    if n <= 1:
        return acc
    return fact_tail(n - 1, n * acc)

def fact_loop(n):  # TCO가 만드는 것과 동등한 반복문
    acc = 1
    while n > 1:
        n, acc = n - 1, n * acc
    return acc

