text-tokenization.pseudocode:
def bpe_train(words, num_merges):
    # words: {문자 튜플: 빈도}, 예: {('l','o','w'): 5}
    vocab, merges = dict(words), []
    for _ in range(num_merges):
        pairs = {}
        for w, f in vocab.items():  # 인접 기호 쌍 빈도
            for a, b in zip(w, w[1:]):
                pairs[(a, b)] = pairs.get((a, b), 0) + f
        if not pairs:
            break
        best = max(pairs, key=pairs.get)  # 최빈 쌍 병합
        merges.append(best)
        new_vocab = {}
        for w, f in vocab.items():
            out, i = [], 0
            while i < len(w):
                if w[i:i + 2] == best:  # 쌍이면 하나로 합침
                    out.append(w[i] + w[i + 1])
                    i += 2
                else:
                    out.append(w[i])
                    i += 1
            new_vocab[tuple(out)] = f
        vocab = new_vocab
    return merges  # 병합 규칙 순서 = 서브워드 어휘

tf-idf.pseudocode:
def tf_idf(docs):
    # docs: 토큰 리스트들의 리스트
    N = len(docs)
    df = {}
    for d in docs:
        for t in set(d):
            df[t] = df.get(t, 0) + 1  # 단어가 나온 문서 수
    vectors = []
    for d in docs:
        vec = {}
        for t in set(d):
            tf = d.count(t) / len(d)  # 문서 내 상대 빈도
            idf = log(N / df[t])  # 모든 문서에 나오면 0
            vec[t] = tf * idf
        vectors.append(vec)
    return vectors

thread-pool.pseudocode:
class ThreadPool:
    def __init__(self, n, queue_max):
        self.q = BlockingQueue(queue_max)  # 작업 큐
        for _ in range(n):  # 스레드를 미리 생성
            start_thread(self.worker)

    def submit(self, task):
        if not self.q.offer(task):  # 큐가 가득 참
            raise RejectedError()  # 거부 정책

    def worker(self):
        while True:
            task = self.q.take()  # 작업 없으면 대기
            try:
                task()
            except Exception as e:
                log(e)  # 스레드는 종료 없이 재사용

three-way-partitioning.pseudocode:
def partition3(a, lo, hi):  # 네덜란드 국기 분할
    pivot = a[lo]
    lt, i, gt = lo, lo, hi
    while i <= gt:
        if a[i] < pivot:
            a[lt], a[i] = a[i], a[lt]
            lt += 1
            i += 1
        elif a[i] > pivot:
            a[i], a[gt] = a[gt], a[i]
            gt -= 1  # i 유지: 교환해 온 값은 미검사
        else:
            i += 1
    return lt, gt  # a[lt..gt] 모두 pivot

def quicksort3(a, lo, hi):
    if lo >= hi:
        return
    lt, gt = partition3(a, lo, hi)
    quicksort3(a, lo, lt - 1)  # 같은 키 구간은 제외
    quicksort3(a, gt + 1, hi)

