        self.next = 0  # 다음 발급 번호
        self.owner = 0  # 현재 서비스 중인 번호

    def acquire(self):
        my = fetch_and_add(self, 'next', 1)  # 원자적 번호표
        while self.owner != my:
            pass  # 내 차례까지 스핀

    def release(self):
        self.owner += 1  # 다음 번호에게 넘김

time-quantum.pseudocode:
def round_robin(procs, q):  # procs: [(이름, 버스트)], 모두 0 도착
    ready = list(procs)
    t, done = 0, {}
    while ready:
        name, burst = ready.pop(0)
        run = min(q, burst)  # 최대 q만큼 실행
        t += run
        if burst > run:
            ready.append((name, burst - run))  # 큐 뒤로
        else:
            done[name] = t  # 완료 시각 = 반환시간
    return done

# round_robin([('A', 5), ('B', 3)], 2) → {'B': 7, 'A': 8}

timestamp-ordering.pseudocode:
def read(Ti, X):
    if TS[Ti] < W_TS[X]:  # 더 젊은 Tj가 이미 기록
        return restart(Ti)  # 새 타임스탬프로 재시작
    R_TS[X] = max(R_TS[X], TS[Ti])
    return X.value

def write(Ti, X, value, thomas=False):
    if TS[Ti] < R_TS[X]:  # 더 젊은 Tj가 이미 읽음
        return restart(Ti)
    if TS[Ti] < W_TS[X]:  # 더 젊은 Tj가 이미 기록
        if thomas:
            return  # 토마스 규칙: 무시
        return restart(Ti)
    X.value = value
    W_TS[X] = TS[Ti]

tokenization.pseudocode:
class TokenVault:  # 원본은 금고(토큰 서버)에만 보관
    def __init__(self):
        self.store = {}  # token → 암호화된 원본

    def tokenize(self, pan):
        while True:  # 원본과 수학적 관계 없는 난수 토큰
            token = pan[:6] + random_digits(6) + pan[-4:]
            if token not in self.store and token != pan:
                break
        self.store[token] = encrypt(pan)
        return token  # 형식 보존: 16자리 숫자 유지

    def detokenize(self, token, caller):
        if not authorized(caller):  # 금고 접근 통제
            raise PermissionError('권한 없음')
        return decrypt(self.store[token])

# 가맹점 DB에는 토큰만 저장 → PCI DSS 범위 축소
# 암호화와 달리 키로 역산 불가, 금고 조회로만 복원

topic-modeling.pseudocode:
def lda_gibbs(docs, K, V, alpha, beta, iters):
    # docs: 단어 ID 리스트들, K: 토픽 수, V: 어휘 크기
    ndk = [[0] * K for _ in docs]  # 문서-토픽 빈도
    nkw = [[0] * V for _ in range(K)]  # 토픽-단어 빈도
    nk = [0] * K
    z = [[randrange(K) for _ in doc] for doc in docs]
    def count(d, w, k, c):
        ndk[d][k] += c
        nkw[k][w] += c
        nk[k] += c
    for d, doc in enumerate(docs):
        for i, w in enumerate(doc):
            count(d, w, z[d][i], 1)
    for _ in range(iters):
        for d, doc in enumerate(docs):
            for i, w in enumerate(doc):
                count(d, w, z[d][i], -1)  # 현재 할당 제외
                p = [(ndk[d][k] + alpha)
                     * (nkw[k][w] + beta)
                     / (nk[k] + V * beta) for k in range(K)]
                z[d][i] = sample_index(p)  # 비례 확률로 재샘플
                count(d, w, z[d][i], 1)
    return ndk, nkw

topological-sort.pseudocode:
def topo_sort(graph):  # Kahn 알고리즘, O(V+E)
    indeg = {v: 0 for v in graph}
    for u in graph:
        for v in graph[u]:
            indeg[v] += 1
    queue = [v for v in graph if indeg[v] == 0]
    order = []
    while queue:
        u = queue.pop(0)
        order.append(u)
        for v in graph[u]:  # u의 나가는 간선 제거
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    if len(order) < len(graph):
        return None  # 순환 존재 -> 위상정렬 불가
    return order

tournament-selection.pseudocode:
def tournament_select(population, fitness, k):
    contenders = random_sample(population, k)  # 무작위 k개
    return max(contenders, key=fitness)  # 그중 최우수 1개

def select_parents(population, fitness, k, n):
    # 토너먼트를 n번 독립 수행 → 병렬화 용이
    return [tournament_select(population, fitness, k)
            for _ in range(n)]
# k=1이면 무작위 선택, k=집단 크기면 항상 최우수

traveling-salesman-problem.pseudocode:
def tour_length(tour, d):
    n = len(tour)
    return sum(d[tour[i]][tour[(i + 1) % n]]
               for i in range(n))

def two_opt(tour, d):
    best = tour_length(tour, d)
    improved = True
    while improved:  # 개선이 없을 때까지 반복
        improved = False
        for i in range(1, len(tour) - 1):
            for j in range(i + 1, len(tour)):
                # i..j 구간을 뒤집어 간선 두 개를 교체
                new = (tour[:i] + tour[i:j + 1][::-1]
                       + tour[j + 1:])
                length = tour_length(new, d)
                if length < best:
                    tour, best, improved = new, length, True
    return tour  # 지역 최적 (전역 최적은 보장 안 됨)

tree.pseudocode:
def preorder(n):  # 부모 먼저
    if n is None:
        return
    visit(n)
    for c in n.children:
        preorder(c)

def postorder(n):  # 자식 먼저
    if n is None:
        return
    for c in n.children:
        postorder(c)
    visit(n)

def level_order(root):  # 레벨 순(BFS)
    q = [root]
    while q:
        n = q.pop(0)
        visit(n)
        q.extend(n.children)

tree-of-thoughts.pseudocode:
def tot_bfs(problem, llm, steps, k, b):
    frontier = [[]]  # 각 상태 = 지금까지의 생각 목록
    for _ in range(steps):
        cands = []
        for state in frontier:
            # 상태마다 다음 생각 후보 k개 생성
            for t in llm.propose(problem, state, k):
                cands.append(state + [t])
        # LLM이 각 경로의 유망도를 스스로 평가
        cands.sort(key=lambda s: llm.evaluate(problem, s),
                   reverse=True)
        frontier = cands[:b]  # 상위 b개만 유지(빔)
    return frontier[0]

trie.pseudocode:
class TrieNode:
    def __init__(self):
        self.children = {}  # 문자 -> 자식 노드
        self.is_end = False

def insert(root, key):
    node = root
    for ch in key:
        if ch not in node.children:
            node.children[ch] = TrieNode()
        node = node.children[ch]
    node.is_end = True  # 키 종료 표시

def search(root, key, prefix=False):
    node = root
    for ch in key:  # O(키 길이), 원소 수와 무관
        if ch not in node.children:
            return False
        node = node.children[ch]
    return True if prefix else node.is_end

