upper-confidence-bound-for-trees.pseudocode:
def uct_select(node, c=1.414):
    # 승률(활용) + 탐험 항이 최대인 자식
    return max(node.children, key=lambda ch:
               ch.w / ch.n
               + c * sqrt(log(node.n) / ch.n))

def mcts(root, iters):
    for _ in range(iters):
        node = root
        # 1 선택: 완전 확장된 노드는 UCT로 하강
        while node.fully_expanded() and node.children:
            node = uct_select(node)
        if not node.terminal():  # 2 확장
            node = node.expand_one()
        reward = rollout(node.state)  # 3 시뮬레이션
        while node:  # 4 역전파(2인 게임은 부호 교대)
            node.n += 1
            node.w += reward
            node = node.parent
    return max(root.children, key=lambda ch: ch.n)

url-shortener.pseudocode:
ALPHABET = ('0123456789abcdefghijklmnopqrstuvwxyz'
            'ABCDEFGHIJKLMNOPQRSTUVWXYZ')  # 62자

def encode(n):  # DB 일련번호 → 짧은 코드 (62진수)
    if n == 0:
        return ALPHABET[0]
    code = ''
    while n > 0:
        n, r = divmod(n, 62)
        code = ALPHABET[r] + code
    return code

def shorten(long_url, db):
    new_id = db.insert(long_url)  # 자동 증가 ID
    return 'https://sho.rt/' + encode(new_id)

def resolve(code, db):
    n = 0
    for ch in code:  # 62진수 → 10진수
        n = n * 62 + ALPHABET.index(ch)
    return db.get(n)  # 301/302 리다이렉트 대상

# encode(10**9) → '15FTGg' (6자로 10억 개 표현)

