utf-8.pseudocode:
def utf8_encode_cp(cp):
    if cp <= 0x7F:
        return [cp]  # ASCII 1바이트
    elif cp <= 0x7FF:
        return [0xC0 | (cp >> 6),
                0x80 | (cp & 0x3F)]
    elif cp <= 0xFFFF:  # 한글 등 3바이트
        return [0xE0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F)]
    else:  # 보충 평면 4바이트
        return [0xF0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3F),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F)]

variance-reduction.pseudocode:
def mc_antithetic(f, n):
    # U와 1-U 쌍: 음의 상관으로 분산 감소
    total = 0.0
    for _ in range(n // 2):
        u = rand()
        total += (f(u) + f(1 - u)) / 2
    return total / (n // 2)

def mc_control(f, g, g_mean, n):
    # g: 기댓값 g_mean을 아는 통제변수
    xs = [rand() for _ in range(n)]
    fx = [f(x) for x in xs]
    gx = [g(x) for x in xs]
    mf, mg = sum(fx) / n, sum(gx) / n
    cov = sum((a - mf) * (b - mg) for a, b in zip(fx, gx))
    var = sum((b - mg) ** 2 for b in gx)
    c = cov / var  # 최적 계수 c* = Cov(f,g)/Var(g)
    return mf - c * (mg - g_mean)

vector-clock.pseudocode:
class VectorClock:
    def __init__(self, n, me):
        self.v = [0] * n
        self.me = me  # 자기 노드 인덱스

    def tick(self):  # 로컬 이벤트·송신
        self.v[self.me] += 1
        return list(self.v)

    def receive(self, other):  # 원소별 max 후 증가
        self.v = [max(a, b) for a, b in zip(self.v, other)]
        self.v[self.me] += 1

def compare(a, b):
    if a == b:
        return 'equal'
    if all(x <= y for x, y in zip(a, b)):
        return 'a → b'  # a가 b에 인과적으로 선행
    if all(x >= y for x, y in zip(a, b)):
        return 'b → a'
    return 'concurrent'  # 동시 갱신(충돌)

