visitor-pattern.pseudocode:
class Number:
    def __init__(self, v):
        self.v = v
    def accept(self, visitor):  # 1차 디스패치: 요소 타입
        return visitor.visit_number(self)

class Add:
    def __init__(self, l, r):
        self.l, self.r = l, r
    def accept(self, visitor):
        return visitor.visit_add(self)

class EvalVisitor:  # 새 연산 = 새 방문자 클래스
    def visit_number(self, n):  # 2차: 방문자 타입
        return n.v
    def visit_add(self, a):
        return a.l.accept(self) + a.r.accept(self)

class PrintVisitor:  # 요소 클래스는 수정 없음
    def visit_number(self, n):
        return str(n.v)
    def visit_add(self, a):
        return f'({a.l.accept(self)}+{a.r.accept(self)})'

voting-ensemble.pseudocode:
def voting_predict(models, x, mode='hard'):
    if mode == 'hard':  # 예측 클래스 다수결
        votes = [m.predict(x) for m in models]
        return max(set(votes), key=votes.count)
    # soft: 클래스별 확률 평균 후 최댓값 선택
    probs = [m.predict_proba(x) for m in models]  # dict
    avg = {c: sum(p[c] for p in probs) / len(probs)
           for c in probs[0]}
    return max(avg, key=avg.get)

