word-sense-disambiguation.pseudocode:
def simplified_lesk(word, sentence, senses):
    # senses: {의미: 사전 뜻풀이 문장}
    context = set(tokenize(sentence)) - {word}
    best, best_overlap = None, -1
    for sense, gloss in senses.items():
        # 문맥 단어와 뜻풀이 단어의 중첩 수
        overlap = len(context & set(tokenize(gloss)))
        if overlap > best_overlap:
            best, best_overlap = sense, overlap
    return best  # 가장 많이 겹치는 의미 선택

x-509.pseudocode:
def validate_chain(chain, anchors, now):
    # chain[0]: 리프(서버) 인증서 → 상위 CA 순서
    for i, cert in enumerate(chain):
        if not (cert.not_before <= now <= cert.not_after):
            return False  # 유효기간 위반
        if is_revoked(cert):  # CRL·OCSP 조회
            return False
        if i + 1 < len(chain):
            issuer = chain[i + 1]
        else:
            issuer = anchors.get(cert.issuer)  # 신뢰 루트
            if issuer is None:
                return False  # 신뢰 앵커에 도달 못함
        if i > 0 and not cert.is_ca:
            return False  # 중간 인증서는 CA여야 함
        if cert.issuer != issuer.subject:
            return False  # 발급자-주체 이름 연결 확인
        if not verify_sig(issuer.public_key, cert):
            return False  # 상위 공개키로 tbs 서명 검증
    return True

xgboost.pseudocode:
def split_gain(GL, HL, GR, HR, lam, gamma):
    # 2차 근사 목적함수 감소량 − 잎 추가 벌점 γ
    def score(G, H):
        return G * G / (H + lam)
    return 0.5 * (score(GL, HL) + score(GR, HR)
                  - score(GL + GR, HL + HR)) - gamma

def best_split(samples, lam=1.0, gamma=0.0):
    # samples: (특성값, g, h) → 정렬 후 왼쪽 누적합으로 탐색
    samples = sorted(samples)
    G = sum(s[1] for s in samples)
    H = sum(s[2] for s in samples)
    GL = HL = 0.0
    best = (0.0, None)
    for i in range(len(samples) - 1):
        GL += samples[i][1]
        HL += samples[i][2]
        if samples[i][0] == samples[i + 1][0]:
            continue  # 같은 값 사이는 분할 불가
        gain = split_gain(GL, HL, G - GL, H - HL,
                          lam, gamma)
        if gain > best[0]:
            thr = (samples[i][0] + samples[i + 1][0]) / 2
            best = (gain, thr)
    return best  # 이득 ≤ 0 이면 분할하지 않음

xunit.pseudocode:
def run_suite(test_cases):
    result = {'pass': 0, 'fail': 0, 'error': 0}
    for case in test_cases:
        fixture = case.setUp()  # 픽스처 준비
        try:
            case.test(fixture)  # 내부 assert로 자동 판정
            result['pass'] += 1
        except AssertionError:
            result['fail'] += 1  # 기대값 불일치
        except Exception:
            result['error'] += 1  # 예기치 않은 예외
        finally:
            case.tearDown(fixture)  # 항상 정리
    return result
